writeFile('credits.lua', [[
-- Compatibility reads plus explicit, acknowledged house round transactions.
-- Disk files are identities only. No local balance is ever imported or written.
local config=require('derby.config')
local ui=require('derby.ui')
local M={}
local client
local bindings={}
-- Captured handles are updated from authoritative terms after a recovered raise.
local handles={}
local function remember(round)
 local refs=handles[round.round] or {}; handles[round.round]=refs; refs[round]=true
end
local function blocked(cli)
 local recovery=cli:localState().recovery
 if recovery then return {ok=false,pending=true,error='Round recovery must finish before another action',request=recovery.request} end
end
local function mutation(cli,q)
 local r=blocked(cli) or cli:mutate(q)
 return r,{pending=r.offline==true or r.pending==true,request=q}
end
local function demo()
 return not config.read() and (_G.ARCADE_DEV_MODE or (arcadeos and arcadeos.freeplay()))
end
local function network()
 if not client then client=require('derby.client').new() end
 return client
end
local function cardAt(path)
 if not path then return ui.card() end
 if path=='freeplay' and demo() then return {account='exhibition',path=path} end
 if not fs.exists(path..'/house-card.json') then return nil end
 local f=fs.open(path..'/house-card.json','r'); local ok,c=pcall(textutils.unserializeJSON,f.readAll()); f.close()
 if ok and type(c)=='table' then return {account=c.account,path=path} end
end
local function account(path)
 local bound=bindings[path or 'default']
 if bound then return bound end
 local c=cardAt(path); return c and c.account
end
local function checked(r)
 if not r.ok then error('HOUSE: '..tostring(r.error)..'. Funds remain at the host; use house station R to retry an unacknowledged request.',0) end
 return r
end
function M.findCards()
 if demo() then return {{path='freeplay',side='freeplay',name='EXHIBITION',credits=999}} end
 local cards={}
 for _,name in ipairs(peripheral.getNames()) do
  if peripheral.getType(name)=='drive' then
   local path=disk.getMountPath(name); local c=path and cardAt(path)
   if c and c.account then
    local r=checked(network():read({op='lookup',account=c.account}))
    cards[#cards+1]={path=path,side=name,name=r.name,credits=r.balance,account=c.account}
   end
  end
 end
 return cards
end
function M.get(path)
 if demo() then return 999 end
 local id=account(path); if not id then return 0 end
 return checked(network():read({op='lookup',account=id})).balance
end
function M.getName(path)
 if demo() then return 'EXHIBITION' end
 local id=account(path); if not id then return nil end
 return checked(network():read({op='lookup',account=id})).name
end
function M.lock(path)
 local c=cardAt(path); assert(c and c.account,'Insert a house account card')
 bindings[path or 'default']=c.account; return true
end
function M.unlock(path) bindings[path or 'default']=nil end
function M.beginRound(game,stake,maximum,path)
 if demo() then return {demo=true,game=game,stake=stake,maximum=maximum,account='exhibition'} end
 local c=cardAt(path); if not c or not c.account then return nil,'Insert a house account card' end
 local cli=network(); local localState=cli:localState()
 local old=localState.rounds[c.account]
 -- A lost reservation reply may have been recovered from another house screen.
 if not old and localState.last and localState.last.result.ok then
  local q=localState.last.request
  if q.op=='reserve' and q.account==c.account then old={round=q.round} end
 end
 if old then
  local status=cli:read({op='roundStatus',round=old.round,account=c.account})
  if not status.ok or status.status=='open' then return nil,'Interrupted round '..old.round..': cashier must review/refund it' end
 end
 local id='arcade:'..os.getComputerID()..':'..(localState.counter+1)
 local q={op='reserve',account=c.account,game=game,stake=stake,maximum=maximum,round=id}
 local r,context=mutation(cli,q)
 if not r.ok then return nil,r.error,context end
 local round={account=c.account,round=id,game=game,stake=stake,maximum=maximum}
 localState=cli:localState(); localState.rounds[c.account]=round; cli:saveLocal(localState)
 bindings[path or 'default']=c.account; remember(round)
 return round
end
function M.increaseRound(round,stake,maximum)
 if round.demo then round.stake=round.stake+stake; round.maximum=maximum; return true end
 remember(round)
 local r,context=mutation(network(),{op='increase',round=round.round,account=round.account,stake=stake,maximum=maximum})
 if not r.ok then return false,r.error,context end
 round.stake=round.stake+stake; round.maximum=maximum
 local s=network():localState(); s.rounds[round.account]=round; network():saveLocal(s)
 return true
end
function M.settleRound(round,amount)
 if round.demo then return 999 end
 local r=checked((mutation(network(),{op='settle',round=round.round,account=round.account,amount=amount})))
 local s=network():localState(); s.rounds[round.account]=nil; network():saveLocal(s); handles[round.round]=nil
 return r.balance
end
function M.refundRound(round)
 if round.demo then return true end
 checked((mutation(network(),{op='refund',round=round.round,account=round.account})))
 local s=network():localState(); s.rounds[round.account]=nil; network():saveLocal(s); handles[round.round]=nil; return true
end
-- Return the original receipt identity as well as its result. Reconciliation is
-- persisted before its read can yield, so a missing status reply keeps all new
-- mutations blocked until retry completes, including after client recreation.
function M.retry()
 if demo() then return true,{ok=true} end
 local cli=network(); local s=cli:localState(); local r,q
 if s.recovery then r,q=s.recovery.result,s.recovery.request
 else
  r=cli:retry(); s=cli:localState(); q=s.pending or (s.last and s.last.request)
 end
 local context={request=q,pending=r.offline==true or r.pending==true}
 if not r.ok then return false,r.error,q and q.account,context end
 if q and (q.op=='reserve' or q.op=='increase') then
  s.recovery={request=q,result=r}; cli:saveLocal(s)
  local status=cli:read({op='roundStatus',round=q.round,account=q.account})
  local function integer(n) return type(n)=='number' and n>=0 and n%1==0 and n<=1000000000 end
  if not status.ok or not integer(status.stake) or not integer(status.maximum) or status.maximum<status.stake then
   context.pending=true
   return false,status.error or 'House did not return authoritative round terms',q.account,context
  end
  context.status=status.status
  local saved=s.rounds[q.account]
  if saved and saved.round~=q.round then
   context.pending=true; return false,'A different account round requires cashier review',q.account,context
  end
  local game=(saved and saved.game) or q.game
  local round={account=q.account,round=q.round,game=game,stake=status.stake,maximum=status.maximum}
  for handle in pairs(handles[q.round] or {}) do
   if handle.account==q.account then handle.stake=status.stake; handle.maximum=status.maximum end
  end
  context.round=round
  if status.status=='open' then s.rounds[q.account]=round
  elseif status.status=='settled' or status.status=='refunded' then
   -- The increase receipt predates an operator refund/settlement. Read this
   -- explicit account, never the card path or that stale receipt balance.
   local balance=cli:read({op='lookup',account=q.account})
   local amount=balance.balance
   local validBalance=type(amount)=='number' and amount>=0 and amount<math.huge and amount%1==0
   if not balance.ok or not validBalance then
    context.pending=true; return false,balance.error or 'House balance unavailable',q.account,context
   end
   context.balance=balance.balance; s.rounds[q.account]=nil; handles[q.round]=nil
  else context.pending=true; return false,'Unknown host round status',q.account,context end
  s.recovery=nil; cli:saveLocal(s)
  if status.status~='open' then return false,'Round '..status.status..'; the interrupted hand cannot continue',q.account,context end
 elseif q and (q.op=='settle' or q.op=='refund') then
  if s.rounds[q.account] and s.rounds[q.account].round==q.round then s.rounds[q.account]=nil; cli:saveLocal(s) end
  handles[q.round]=nil
 end
 return true,r,q and q.account,context
end
-- Unchecked edits must fail loudly if a forgotten consumer tries the old API.
function M.set() error('HOUSE: local balance editing is retired',0) end
function M.add() error('HOUSE: use settleRound with an acknowledged reservation',0) end
function M.remove() error('HOUSE: use beginRound with a maximum return',0) end
function M.setName() error('HOUSE: account names belong to the host',0) end
return M
]])

writeFile('dedicate.lua', [[
-- dedicate.lua
-- Simple installer for dedicated (kiosk) machines.
-- Writes .arcade_config + kiosk flag files, then reboots.

local function clear()
    term.setBackgroundColor(colors.black)
    term.setTextColor(colors.white)
    term.clear()
    term.setCursorPos(1, 1)
end

local function writeFile(path, content)
    local f = fs.open(path, "w")
    if not f then return false end
    f.write(content)
    f.close()
    return true
end

local function deleteFile(path)
    if fs.exists(path) then
        fs.delete(path)
    end
end

local function isKioskEnabled()
    return fs.exists(".kiosk_mode")
end

local function currentCmd()
    if not fs.exists(".arcade_config") then return nil end
    local f = fs.open(".arcade_config", "r")
    if not f then return nil end
    local cmd = (f.readAll() or "")
    f.close()
    cmd = cmd:gsub("%s+", "")
    if cmd == "" then return nil end
    return cmd
end

local function pause()
    while true do
        local e, p1 = os.pullEvent()
        if e == "key" or e == "mouse_click" or e == "monitor_touch" then
            return
        end
    end
end

clear()
print("DEDICATED INSTALLER")
print("===================")
print("")
print("This will configure this computer to run")
print("only one game (kiosk mode).")
print("")
print("Current: " .. tostring(currentCmd() or "<none>"))
print("Kiosk:   " .. (isKioskEnabled() and "ON" or "OFF"))
print("")
print("1) Dedicated: Can't Stop (spawn)")
print("2) Disable kiosk (return to normal)")
print("")
print("Press 1 or 2...")

while true do
    local e, key = os.pullEvent("key")
    local name = keys.getName(key)

    if name == "one" or name == "numPad1" then
        -- Dedicated Can't Stop
        clear()
        print("Installing: Can't Stop kiosk...")
        writeFile(".arcade_config", "cant_stop")
        writeFile(".kiosk_mode", "1")
        writeFile(".kiosk_game", "cant_stop")
        print("Done. Rebooting...")
        sleep(1)
        os.reboot()

    elseif name == "two" or name == "numPad2" then
        -- Disable kiosk mode
        clear()
        print("Disabling kiosk mode...")
        deleteFile(".kiosk_mode")
        deleteFile(".kiosk_game")
        print("Done.")
        print("Tip: run setup.lua or edit .arcade_config")
        print("to choose a different default program.")
        print("")
        print("Rebooting...")
        sleep(1)
        os.reboot()
    end
end
]])

writeFile('derby/app.lua', [[
local M={}
function M.display(client,t,demo,verify)
 local sim=require('derby.sim'); local render=require('derby.render').new(t)
 local camera=settings.get('derby.camera','follow')
 local snapshot={phase='CONNECTING',positions={0,0,0},order={}}
 local race=demo and sim.new(1977); local tick=0
 local nextStep=os.epoch('utc'); local started=nextStep; local frames=0
 local sfx=require('derby.sfx').new()
 local timer=os.startTimer(.05)
 while true do
  local e,a,b,c=os.pullEvent()
  if e=='timer' and a==timer then
   if demo then
    local now=os.epoch('utc')
    while now>=nextStep do
     tick=tick+1; nextStep=nextStep+100
     if tick>30 and #race.order<3 then sim.step(race) end
    end
    snapshot={phase=tick<=30 and 'LOCKED' or (#race.order==3 and 'RESULT' or 'RUNNING'),positions=sim.positions(race),order=race.order,tick=race.tick,seconds=tick<=30 and math.ceil((30-tick)/10) or 0}
    if verify and #race.order==3 then
     local f=assert(fs.open('/derby-exhibition.json','w'))
     f.write(textutils.serializeJSON({seed=race.seed,order=race.order,frames=frames,elapsed=(now-started)/1000,fps=frames/math.max(.001,(now-started)/1000)})); f.close(); verify=false
    end
    if tick>race.tick+180 then race=sim.new(race.seed+1); tick=0 end
   else
    local r=client:read({op='snapshot'})
    snapshot=r.ok and r or {phase='HOUSE OFFLINE',positions=snapshot.positions,order={},paused=true}
   end
   sfx:hear(snapshot,os.epoch('utc'))
   render:draw(snapshot,camera,demo); frames=frames+1; timer=os.startTimer(.05)
  elseif e=='key' then
   if a==keys.q or a==keys.backspace then return
   elseif a==keys.c then camera=camera=='follow' and 'overview' or camera=='overview' and 'finish' or 'follow'
   elseif a==keys.one then camera='follow' elseif a==keys.two then camera='overview' elseif a==keys.three then camera='finish' end
   settings.set('derby.camera',camera); settings.save('/derby-settings')
   render:draw(snapshot,camera,demo)
  elseif e=='term_resize' or e=='monitor_resize' then render:draw(snapshot,camera,demo) end
 end
end
local function run(args)
 local config=require('derby.config'); local ui=require('derby.ui')
 settings.load('/derby-settings')
 local command=args[1] or 'station'
 if command=='--demo' or command=='demo' or (command=='station' and not config.read() and arcadeos and arcadeos.freeplay()) then return M.display(nil,ui.target(),true,args[2]=='--verify') end
 if command=='setup' then return config.setup(args[2],args[3],args[4]) end
 local c=config.read()
 if not c then print('House is not configured. Exhibition: race --demo'); print('Configure: house setup station <wired-modem> <host-id>'); return end
 if command=='host' then assert(c.role=='host','Configure this computer as the host'); return require('derby.server').run(c) end
 local client=require('derby.client').new(c)
 if command=='display' then return M.display(client,ui.target(),false)
 elseif command=='cashier' then assert(c.role=='cashier','Configure this computer as cashier'); return require('derby.cashier').run(client,ui.target())
 elseif command=='station' then return require('derby.station').run(client,ui.target()) end
 error('Use: house host|display|station|cashier|setup or race --demo',0)
end
function M.run(args)
 local t=require('derby.ui').target()
 local restore=require('derby.palette').save(t)
 local old=term.current()
 local ok,err=xpcall(function() run(args) end,debug.traceback)
 term.redirect(old); restore()
 if not ok then error(err,0) end
end
return M
]])

writeFile('derby/cage.lua', [[
-- The cashier's cage: a Pine3D croupier's booth seen from the customer's side of the bars.
-- Camera on -x looking +x; y is up and +z is screen right, like the casino tables.
-- The brass pass-through tray in the middle of the bars carries the pile of diamonds
-- you are about to move; the vault plaque at the back shows the card's balance.
local pine=require('derby.vendor.Pine3D')
local mesh=require('casino.mesh')
local font=require('casino.font')
local M={}
M.minW,M.minH=39,19
local tri,quad,box=mesh.tri,mesh.quad,mesh.box
M.trayX,M.trayY=-3.6,1.42
M.vaultX=4.4
-- A cut gem centred on (cx,cy,cz) with half-width s: pale crown above, cyan pavilion below.
local function gem(m,cx,cy,cz,s)
 local top,bot={cx,cy+.55*s,cz},{cx,cy-.75*s,cz}
 local ring={{cx+s,cy,cz},{cx,cy,cz+s},{cx-s,cy,cz},{cx,cy,cz-s}}
 for i=1,4 do
  local a,b=ring[i],ring[i%4+1]
  local mid={(a[1]+b[1])/2,cy,(a[3]+b[3])/2}
  local up={mid[1]-cx,.8,mid[3]-cz}; local down={mid[1]-cx,-.8,mid[3]-cz}
  tri(m,a,b,top,i%2==0 and colors.white or colors.lightBlue,up)
  tri(m,a,b,bot,colors.cyan,down)
 end
end
-- A pyramid of n gems (at most 30) resting on y=0, filling the bottom layer first.
function M.pile(n)
 local m={}; local step,s=.5,.22
 local layers={4,3,2,1}; local placed=0
 for k,side in ipairs(layers) do
  local off=-(side-1)*step/2
  for row=0,side-1 do for col=0,side-1 do
   if placed>=n then return m end
   placed=placed+1
   gem(m,off+row*step,s*.75+(k-1)*.3,off+col*step,s)
  end end
 end
 return m
end
-- A stack of chips as stacked flat boxes, colour per stack.
local function chipStack(m,x,z,n,color)
 for i=0,n-1 do box(m,x,M.trayY-.12+i*.07,z,.42,.06,.42,i%2==0 and color or colors.white) end
end
-- Digits as lit glyphs on the vault plaque; blank (just the plaque) when there is no balance.
function M.plaque(text)
 local m={}
 box(m,M.vaultX+1.46,2.05,-2.6,.04,1.7,5.2,colors.yellow)
 box(m,M.vaultX+1.42,2.1,-2.5,.04,1.6,5,colors.black)
 if text and text~='' then
  local cell=math.min(.26,4.6/(#text*3.6))
  local w=font.width(text)*cell
  font.draw(m,text,-w/2,2.1+1.6/2+2.5*cell,cell,colors.lime,function(u,v) return {M.vaultX+1.41,v,u} end,{-1,0,0})
 else
  box(m,M.vaultX+1.41,2.7,-.6,.01,.1,1.2,colors.red)
 end
 return m
end
-- The fixed room: floor, panelled walls, croupier's table, safe, shelves, bars.
function M.room()
 local m={}
 local dark,wood,gold=colors.gray,colors.brown,colors.yellow
 box(m,-16,-.5,-9,28,.5,18,wood)
 -- Back and side walls: panelled below a gold rail, plaster above.
 box(m,M.vaultX+1.5,-.5,-9,.6,7,18,dark)
 box(m,M.vaultX+1.4,0,-9,.1,1.4,18,wood)
 box(m,M.vaultX+1.35,1.4,-9,.1,.12,18,gold)
 box(m,-16,-.5,9,28,7,.6,dark); box(m,-16,-.5,-9.6,28,7,.6,dark)
 box(m,-16,1.4,8.9,28,.12,.1,gold); box(m,-16,1.4,-8.9,28,.12,.1,gold)
 -- Croupier's table inside the cage: felt top, wooden skirt, chip racks along its back.
 box(m,-3.0,0,-5.6,4.6,1.3,11.2,wood)
 box(m,-3.0,1.3,-5.6,4.6,.1,11.2,colors.green)
 box(m,-3.0,1.3,-5.7,4.6,.2,.1,wood); box(m,-3.0,1.3,5.6,4.6,.2,.1,wood)
 box(m,1.5,1.3,-5.6,.1,.2,11.2,wood)
 local zs={-4.6,-3.8,-3.0,-2.2,2.2,3.0,3.8,4.6}
 local cs={colors.white,colors.red,colors.blue,colors.lime,colors.black,colors.lime,colors.blue,colors.red}
 for i,z in ipairs(zs) do chipStack(m,.4,z,3+i%4,cs[i]) end
 -- Ledger and a banker's lamp on the felt.
 box(m,-1.6,1.4,-4.4,1.1,.09,.8,colors.white); box(m,-1.6,1.4,-4.45,1.1,.1,.05,colors.red)
 box(m,-1.0,1.4,3.9,.1,.6,.1,gold); box(m,-1.2,2.0,3.7,.5,.2,.5,colors.green)
 -- Safe against the back wall, dial and handle toward the room.
 box(m,M.vaultX-.3,0,3.2,1.8,3.1,3.4,colors.lightGray)
 box(m,M.vaultX-.35,.3,3.4,.06,2.5,3.0,dark)
 box(m,M.vaultX-.42,1.3,4.3,.08,.5,.5,gold); box(m,M.vaultX-.42,1.1,5.0,.08,.9,.14,colors.red)
 -- Shelf of stored gems on the left of the back wall.
 box(m,M.vaultX+.6,1.2,-8.2,.9,.12,4.4,wood); box(m,M.vaultX+.6,2.5,-8.2,.9,.12,4.4,wood)
 for i=0,5 do
  gem(m,M.vaultX+1.0,1.45,-7.6+i*.7,.2); gem(m,M.vaultX+1.0,2.75,-7.6+i*.7,.2)
 end
 -- The cage front: posts, a lintel with the diamond mark, a counter panel and brass bars.
 local x=-3.7
 for _,z in ipairs({-6.2,6.0}) do box(m,x,0,z,.3,5.2,.3,gold) end
 box(m,x,4.4,-6.2,.3,.8,12.5,gold)
 box(m,x-.02,4.55,-.5,.05,.5,1,colors.black)
 quad(m,{x-.06,4.8,0},{x-.06,4.6,.35},{x-.06,4.4,0},{x-.06,4.6,-.35},colors.lightBlue,{-1,0,0})
 box(m,x,0,-6.2,.3,1.3,12.5,wood)
 box(m,x-.05,1.25,-6.3,.4,.07,12.7,gold)
 local z=-5.6
 while z<5.7 do
  if math.abs(z)>1.75 then box(m,x+.1,1.3,z,.07,3.1,.07,gold) end
  z=z+.62
 end
 -- The pass-through tray the diamonds ride on, with a low brass lip.
 box(m,M.trayX-1.0,M.trayY-.2,-1.55,2.2,.1,3.1,gold)
 box(m,M.trayX-1.0,M.trayY-.1,-1.55,2.2,.18,.08,gold); box(m,M.trayX-1.0,M.trayY-.1,1.47,2.2,.18,.08,gold)
 box(m,M.trayX-1.0,M.trayY-.1,-1.55,.08,.18,3.1,gold)
 return m
end
-- Pine3D view: v = {balance, count, dx, hidePile}. Text overlays are drawn below the scene.
local function line(t,y,text,fg,bg)
 local w,h=t.getSize(); if y<1 or y>h then return end
 t.setCursorPos(1,y); t.setBackgroundColor(bg or colors.black); t.setTextColor(fg or colors.white)
 t.write((tostring(text)..string.rep(' ',w)):sub(1,w))
end
M.line=line
-- Three buttons across the bottom two rows; labels sit on the last row.
function M.slots(w)
 local third=math.floor(w/3)
 return {{x1=1,x2=third},{x1=third+1,x2=2*third},{x1=2*third+1,x2=w}}
end
M.barColors={{colors.black,colors.lime},{colors.black,colors.yellow},{colors.white,colors.red}}
function M.new(t)
 assert(t.isColor(),'The cashier cage requires an advanced colour computer or monitor')
 require('derby.palette').apply(t)
 local old=term.redirect(t)
 local w,h=t.getSize()
 local f=pine.newFrame(1,2,w,math.max(1,h-6)); f:setBackgroundColor(colors.black); f:setFoV(48)
 local roomObj=f:newObject(M.room(),0,0,0)
 local plaqueObj,plaqueText=f:newObject(M.plaque(nil),0,0,0),nil
 local piles,pileObj,pileKey={}, nil, nil
 local function aim() mesh.look(f,-13,3.8,0,0,1.7,0) end
 aim()
 term.redirect(old)
 local api={frame=f}
 -- v: balance (number|nil), count, dx (pile offset toward the vault, 0 at the tray),
 -- hidePile, title, info, prompt, status, hint, options={{label},{label},{label}}.
 function api:draw(v)
  local previous=term.redirect(t)
  local ww,hh=t.getSize()
  if ww~=w or hh~=h then w,h=ww,hh; f:setSize(1,2,w,math.max(1,h-6)); aim() end
  if w<M.minW or h<M.minH then
   t.setBackgroundColor(colors.black); t.clear(); line(t,2,'CASHIER: display needs 39 x 19'); line(t,4,'Resize or use a larger monitor.')
   term.redirect(previous); return
  end
  local text=v.balance and tostring(v.balance) or nil
  if text~=plaqueText then plaqueObj:setModel(M.plaque(text)); plaqueText=text end
  local objects={roomObj,plaqueObj}
  local n=math.max(1,math.min(30,v.count or 5))
  if not v.hidePile then
   local model=piles[n]; if not model then model=M.pile(n); piles[n]=model end
   if not pileObj then pileObj=f:newObject(model,0,0,0); pileKey=n
   elseif pileKey~=n then pileObj:setModel(model); pileKey=n end
   pileObj:setPos(M.trayX+(v.dx or 0),M.trayY-.1,0)
   objects[#objects+1]=pileObj
  end
  f:drawObjects(objects); f:drawBuffer()
  line(t,1,' '..(v.title or 'DIAMOND CASHIER'),colors.white,colors.blue)
  local right='1 DIAMOND = 1 CREDIT '
  t.setCursorPos(math.max(1,w-#right+1),1); t.setTextColor(colors.yellow); t.setBackgroundColor(colors.blue); t.write(right)
  line(t,h-5,' '..(v.info or ''),colors.white,colors.gray)
  line(t,h-4,' '..(v.prompt or ''),colors.yellow,colors.black)
  line(t,h-3,' '..(v.status or ''),colors.white,colors.black)
  line(t,h-2,' '..(v.hint or ''),colors.lightGray,colors.black)
  for i,s in ipairs(M.slots(w)) do
   local label=v.options and v.options[i] or ''
   local width=s.x2-s.x1+1; local lp=math.max(0,math.floor((width-#label)/2))
   local fg,bg=M.barColors[i][1],M.barColors[i][2]
   if label=='' then fg,bg=colors.gray,colors.black end
   for row=h-1,h do
    t.setCursorPos(s.x1,row); t.setTextColor(fg); t.setBackgroundColor(bg)
    t.write(row==h and (string.rep(' ',lp)..label..string.rep(' ',width)):sub(1,width) or string.rep(' ',width))
   end
  end
  term.redirect(previous)
 end
 return api
end
return M
]])

writeFile('derby/cashier.lua', [=[
local ui=require('derby.ui')
local currency=require('derby.currency')
local M={}
local slots=require('derby.cage').slots
function M.run(client,t)
 local amounts={5,10,20,64}; local index=1; local status=''; local review
 local card,balance,anim
 local cage
 local policy,entries,selected=nil,{},1
 local apiVersion
 local reviewItem,reviewUnits,reviewBalance
 local function refresh()
  local info=client:read({op='currency'})
  apiVersion=info.ok and info.apiVersion or nil
  policy=info.ok and info.apiVersion==2 and info.policy or nil
  entries={}
  if policy then for id,e in pairs(policy.entries) do if e.depositEnabled or e.redeemEnabled then entries[#entries+1]=id end end; table.sort(entries) end
  if selected>#entries then selected=1 end
  card=ui.card(); balance=nil
  if card and card.account then local r=client:read({op='lookup',account=card.account}); balance=r.ok and r.balance or nil; if not r.ok then status=r.error end end
 end
 local function draw()
  if not ui.usable(t) then return end
  cage=cage or require('derby.cage').new(t)
  local now=os.epoch('utc')/1000
  local dx,hide=0,false
  if anim then
   local u=(now-anim.t0)/anim.dur
   if u>=1 then anim=nil
   else dx=(anim.op=='deposit' and u or 1-u)*7.5; hide=anim.op=='deposit' and u>.85 end
  end
  local entry=policy and policy.entries[entries[selected]]
  local v={balance=balance,count=review and (review.amount or review.requestedItems) or amounts[index],dx=dx,hidePile=hide,status=status,
   info=(card and (card.account or 'New card: issue an account') or 'Insert a floppy disk')..'  |  Balance: '..tostring(balance or 'UNAVAILABLE')}
  if review then
   if review.op=='exchange' then
    v.prompt=review.direction:upper()..' '..review.requestedItems..' '..reviewItem..'?'
    v.hint=reviewUnits..' credits; balance '..reviewBalance..'  Enter: confirm  Backspace: cancel'
   else v.prompt=review.op:upper()..' '..review.amount..' DIAMONDS?'; v.hint='Enter: confirm  Backspace: cancel' end
   v.options={'CONFIRM','','CANCEL'}
  else
   v.prompt=(entry and (entry.itemId..' = '..entry.unitsPerItem..' credits [Up/Down]  ') or '')..'Amount: '..amounts[index]..'  [Left/Right]'
   v.hint='[N] New card  [R] Retry  [Q] Exit'
   v.options={'DEPOSIT',tostring(amounts[index]),'WITHDRAW'}
  end
  cage:draw(v)
 end
 local function create()
  if not ui.usable(t) then return end
  refresh()
  if not card or card.account then status='Insert a disk without a house account'; return end
  local original=card
  local r=client:mutate({op='create',name='Guest'})
  if r.ok then
   local current=ui.card()
   if current and current.diskID==original.diskID and current.path==original.path then
    local f=assert(fs.open(current.path..'/house-card.json','w')); f.write(textutils.serializeJSON({account=r.account})); f.close()
    status='New account issued at zero. Old files preserved.'
   else status='Card removed. New account is empty; issue again.' end
  else status=r.error end
  refresh()
 end
 local function choose(op)
  if not ui.usable(t) then return end
  refresh()
  if apiVersion~=1 and apiVersion~=2 then status='Currency policy unavailable; retry when connected'; return end
  if not (card and card.account and balance) then status='Insert an issued card and connect to house'; return end
  if policy then
   local id=entries[selected]; local e=id and policy.entries[id]
   local direction=op=='deposit' and 'deposit' or 'redeem'
   if not e or not e[direction=='deposit' and 'depositEnabled' or 'redeemEnabled'] then status='This item is disabled for '..direction; return end
   local ok,units=pcall(currency.quote,e,amounts[index],policy)
   if not ok then status='Choose fewer items; configured transfer limit exceeded'; return end
   reviewItem=e.itemId; reviewUnits=units; reviewBalance=balance+(direction=='deposit' and reviewUnits or -reviewUnits)
   review={op='exchange',apiVersion=2,account=card.account,direction=direction,entryId=id,
    requestedItems=amounts[index],policyId=policy.policyId,policyRevision=policy.revision}
  else review={op=op,account=card.account,amount=amounts[index]} end
 end
 local function confirm()
  if not ui.usable(t) then return end
  if not review then return end
  local current=ui.card()
  if not current or current.account~=review.account then status='Card changed. Transfer not sent.'; review=nil; return end
  local r=client:mutate(review)
  status=r.ok and ('Transferred '..tostring(r.confirmedItems or r.moved or 0)..' items; balance '..tostring(r.balance)) or r.error
  if r.ok and (r.confirmedItems or r.moved or 1)>0 then anim={op=(review.op=='exchange' and review.direction=='redeem') and 'withdraw' or (review.op=='exchange' and 'deposit' or review.op),t0=os.epoch('utc')/1000,dur=.9} end
  review=nil; refresh()
 end
 refresh(); draw(); local timer=os.startTimer(.1); local ticks=0
 while true do
  local e,a,b,c=os.pullEvent()
  if e=='timer' and a==timer then ticks=ticks+1; if ticks%10==0 then refresh() end; timer=os.startTimer(.1)
  elseif e=='key' then
   if a==keys.q then return elseif a==keys.backspace then review=nil
   elseif a==keys.enter then confirm()
   elseif a==keys.r then local r=client:retry(); status=r.ok and 'Request acknowledged; check balance' or r.error; refresh()
   elseif not review then
    if policy and #entries>0 and a==keys.up then selected=(selected-2)%#entries+1 elseif policy and #entries>0 and a==keys.down then selected=selected%#entries+1 elseif a==keys.left then index=(index-2)%#amounts+1 elseif a==keys.right then index=index%#amounts+1
    elseif a==keys.n then create() elseif a==keys.d then choose('deposit') elseif a==keys.w then choose('withdraw') end
   end
  elseif e=='monitor_touch' or e=='mouse_click' then
   local w,h=t.getSize()
   if c>=h-1 then
    local slot; for i,s in ipairs(slots(w)) do if b>=s.x1 and b<=s.x2 then slot=i end end
    if review then if slot==1 then confirm() elseif slot==3 then review=nil end
    elseif slot==1 then choose('deposit') elseif slot==2 then index=index%#amounts+1 elseif slot==3 then choose('withdraw') end
   end
  end
  draw()
