writeFile('derby/render.lua', [[
local pine=require('derby.vendor.Pine3D')
local scene=require('derby.scene')
local sim=require('derby.sim')
local M={}
local function line(t,y,text,fg,bg)
 local w,h=t.getSize(); if y>h or y<1 then return end
 t.setCursorPos(1,y); t.setBackgroundColor(bg or colors.black); t.setTextColor(fg or colors.white)
 t.write((text..string.rep(' ',w)):sub(1,w))
end
M.line=line
function M.new(t)
 assert(t.isColor(),'Pine3D Derby requires an advanced colour computer or monitor')
 require('derby.palette').apply(t)
 local old=term.redirect(t)
 local w,h=t.getSize()
 local f=pine.newFrame(1,4,w,math.max(1,h-8)); f:setBackgroundColor(colors.lightBlue); f:setFoV(65)
 local track=f:newObject(scene.track(false),0,0,0)
 local horses={}; local objects={track}; local frames={}
 for i=1,3 do
  frames[i]={}; for p=1,8 do frames[i][p]=scene.horse(i,(p-1)*math.pi/4) end
  horses[i]=f:newObject(frames[i][1],0,0,0); objects[#objects+1]=horses[i]
 end
 term.redirect(old)
 local api={}
 local smooth
 local function look(x,y,z,tx,ty,tz)
  local dx,dz=tx-x,tz-z
  f:setCamera({x=x,y=y,z=z,rotX=-90,rotY=math.deg(math.atan2(dz,dx)),rotZ=math.deg(math.atan2(ty-y,math.sqrt(dx*dx+dz*dz)))})
 end
 function api:draw(v,camera,exhibition)
  local previous=term.redirect(t)
  local ww,hh=t.getSize()
  if ww~=w or hh~=h then w,h=ww,hh; f:setSize(1,4,w,math.max(1,h-8)) end
  if w<39 or h<19 then
   t.setBackgroundColor(colors.black); t.clear(); line(t,2,'DERBY: display needs 39 x 19'); line(t,4,'Resize or use a larger monitor.'); term.redirect(previous); return
  end
  local positions=v.positions or {0,0,0}; local leader=1
  for i=2,3 do if positions[i]>positions[leader] then leader=i end end
  for i,o in ipairs(horses) do
   local x,z,a=scene.pose(positions[i]>=1 and .999 or positions[i],(i-1)*2)
   local running=v.phase=='RUNNING'; local p=running and math.floor((v.tick or 0)*.8)%8+1 or 1
   o:setModel(frames[i][p]); o:setPos(x,running and math.abs(math.sin((v.tick or 0)*.45+i))*.13 or 0,z); o:setRot(0,a,0)
  end
  if camera~='follow' then smooth=nil end
  if camera=='overview' then look(-65,58,60,0,0,0); f:setFoV(68)
  elseif camera=='finish' then look(-36,9,30,-17,1,16); f:setFoV(70)
  elseif v.phase~='RUNNING' then look(-43,15,36,-9,1,16); f:setFoV(70)
  else
   local progress=(positions[1]+positions[2]+positions[3])/3
   local x,z,a=scene.pose(math.min(.999,progress),2)
   local target={x-math.cos(a)*15+math.sin(a)*13,10,z+math.sin(a)*15+math.cos(a)*13,x,1.3,z}
   smooth=smooth or target
   for i=1,6 do smooth[i]=smooth[i]+(target[i]-smooth[i])*.2 end
   look(table.unpack(smooth)); f:setFoV(76)
  end
  f:drawObjects(objects); f:drawBuffer()
  line(t,1,' PINE3D DERBY'..(exhibition and ' | EXHIBITION - NO MONEY' or ' | '..tostring(v.id or 'CONNECTING')),colors.white,colors.blue)
  line(t,2,' '..(v.paused and 'PAUSED' or v.phase or 'CONNECTING')..((v.seconds or 0)>0 and (' | '..v.seconds..' seconds') or ''),colors.yellow)
  local win=v.order and v.order[1]
  line(t,3,win and (' WINNER: '..win..' '..sim.horses[win].name) or ' Same race. Three horses. Pick your winner.',colors.white)
  for i=1,3 do line(t,h-5+i,' '..i..' '..sim.horses[i].name..'  '..math.floor((positions[i] or 0)*100)..'%',colors.white) end
  line(t,h-1,' [C] Camera: '..(camera or 'follow')..'  [Q] Exit',colors.yellow)
  line(t,h,exhibition and ' Practice only | 1=Follow 2=Overview 3=Finish' or ' Bet at a station | 1=Follow 2=Overview 3=Finish',colors.white)
  term.redirect(previous)
 end
 return api
end
return M
]])

writeFile('derby/scene.lua', [[
local M={}
local pi=math.pi
-- A stadium oval: two 40-unit straights and two radius-16 bends.
M.length=80+32*pi
function M.pose(progress,lane)
 local d=(progress%1)*M.length; local r=16+(lane or 0)
 if d<40 then return -20+d,r,0
 elseif d<40+16*pi then local a=(d-40)/16; return 20+math.sin(a)*r,math.cos(a)*r,a
 elseif d<80+16*pi then return 20-(d-40-16*pi),-r,pi
 else local a=(d-80-16*pi)/16; return -20-math.sin(a)*r,-math.cos(a)*r,pi+a end
end
local function tri(m,a,b,c,color)
 m[#m+1]={x1=a[1],y1=a[2],z1=a[3],x2=b[1],y2=b[2],z2=b[3],x3=c[1],y3=c[2],z3=c[3],c=color,forceRender=true}
end
local function quad(m,a,b,c,d,color) tri(m,a,b,c,color); tri(m,a,c,d,color) end
function M.box(m,x,y,z,sx,sy,sz,c)
 local a={x,y,z}; local b={x+sx,y,z}; local d={x,y,z+sz}; local e={x,y+sy,z}; local f={x+sx,y+sy,z}; local g={x+sx,y+sy,z+sz}; local h={x,y+sy,z+sz}; local j={x+sx,y,z+sz}
 quad(m,a,b,f,e,c); quad(m,d,h,g,j,c); quad(m,a,e,h,d,c); quad(m,b,j,g,f,c); quad(m,e,f,g,h,c); quad(m,a,d,j,b,c)
end
function M.track(detail)
 local m={}; local steps=detail and 100 or 56
 quad(m,{-80,-.12,-65},{80,-.12,-65},{80,-.12,65},{-80,-.12,65},colors.green)
 for n=0,steps-1 do
  local a,b=n/steps,(n+1)/steps
  local x1,z1=M.pose(a,-3); local x2,z2=M.pose(a,5)
  local x3,z3=M.pose(b,5); local x4,z4=M.pose(b,-3)
  quad(m,{x1,0,z1},{x2,0,z2},{x3,0,z3},{x4,0,z4},colors.brown)
  for _,offset in ipairs({-3,5}) do
   local x,z=M.pose(a,offset); local xx,zz=M.pose(b,offset)
   quad(m,{x,.85,z},{xx,.85,zz},{xx,1.05,zz},{x,1.05,z},colors.white)
   if n%2==0 then M.box(m,x,.05,z,.14,.95,.14,colors.lightGray) end
  end
 end
 -- Starting gates and finish gantry, at the beginning of the near straight.
 for i=0,3 do M.box(m,-20,.05,13.4+i*2.1,.25,2,.25,colors.lightGray) end
 M.box(m,-20,2,13.4,.4,.3,6.7,colors.yellow)
 for _,z in ipairs({12.3,22}) do M.box(m,-19.7,0,z,.5,5,.5,colors.white) end
 M.box(m,-19.7,4.7,12.3,.5,.7,10.2,colors.black)
 for n=0,7 do
  quad(m,{-20,.02,13+n},{-19,.02,13+n},{-19,.02,14+n},{-20,.02,14+n},n%2==0 and colors.white or colors.black)
 end
 -- Tiered grandstand behind the far straight, so every camera looks across the track at it
 -- rather than through it. A shallow cantilevered roof covers only the back rows.
 for n=0,3 do M.box(m,-16,0,-32-n*2,32,1.2+n*1.2,2, n%2==0 and colors.lightGray or colors.gray) end
 M.box(m,-16,0,-40.5,32,6.2,.5,colors.gray)
 M.box(m,-17,6.2,-41,34,.25,5,colors.red)
 for _,x in ipairs({-16,15.6}) do M.box(m,x,0,-40.5,.4,6.2,.4,colors.white) end
 -- Tote board in the infield: three large light panels instead of tiny scenery text.
 M.box(m,5,0,-5,.5,6,.5,colors.gray); M.box(m,18,0,-5,.5,6,.5,colors.gray)
 M.box(m,4,4,-5.2,15,5,.5,colors.black)
 for i=1,3 do M.box(m,5,4+i,-4.65,12,.5,.1,colors.white) end
 return m
end
-- A box along a line in the side (x-y) plane: used for legs, neck, head and tail so the
-- horse reads as a silhouette instead of a stack of axis-aligned blocks.
function M.limb(m,x1,y1,x2,y2,thick,z,width,c)
 local dx,dy=x2-x1,y2-y1; local len=math.sqrt(dx*dx+dy*dy); if len==0 then return end
 local nx,ny=-dy/len*thick/2,dx/len*thick/2; local z1,z2=z-width/2,z+width/2
 local p={{x1+nx,y1+ny},{x2+nx,y2+ny},{x2-nx,y2-ny},{x1-nx,y1-ny}}
 local function v(k,zz) return {p[k][1],p[k][2],zz} end
 quad(m,v(1,z1),v(2,z1),v(3,z1),v(4,z1),c); quad(m,v(1,z2),v(2,z2),v(3,z2),v(4,z2),c)
 for k=1,4 do local n=k%4+1; quad(m,v(k,z1),v(n,z1),v(n,z2),v(k,z2),c) end
end
-- Coat, mane and jockey silks. Silks match sim.horses[i].color so the UI and track agree.
M.coats={{colors.pink,colors.black},{colors.black,colors.gray},{colors.lightGray,colors.gray}}
M.silks={colors.orange,colors.lightGray,colors.purple}
function M.horse(i,phase)
 local m={}; local coat,mane=M.coats[i][1],M.coats[i][2]; local silk=M.silks[i]
 -- Barrel, chest and rump, then a sloping neck and a head angled toward the ground.
 M.box(m,-.95,1.22,-.36,1.95,.78,.72,coat)
 M.limb(m,.7,1.5,1.3,2.5,.62,0,.52,coat)
 M.limb(m,1.2,2.58,1.95,2.06,.36,0,.4,coat)
 M.box(m,1.08,2.72,-.16,.12,.24,.1,coat); M.box(m,1.08,2.72,.06,.12,.24,.1,coat)
 M.limb(m,.5,1.9,1.08,2.76,.14,0,.2,mane)
 local sway=math.sin(phase)*.12
 M.limb(m,-.92,1.92,-1.5,1.2+sway,.22,0,.2,mane)
 -- Rotary gallop: each leg is a thigh plus a cannon that folds back as the leg swings forward.
 for _,leg in ipairs({{-.68,-.2,0},{-.68,.2,.7},{.68,-.2,pi},{.68,.2,pi+.7}}) do
  local hx,hz,off=leg[1],leg[2],leg[3]
  local swing=math.sin(phase+off)*.5; local fold=math.max(0,math.cos(phase+off))*.9
  local kx,ky=hx+math.sin(swing)*.62,1.4-math.cos(swing)*.62
  local lower=swing-fold
  local fx,fy=kx+math.sin(lower)*.56,ky-math.cos(lower)*.56
  local tx,ty=kx+math.sin(lower)*.72,ky-math.cos(lower)*.72
  M.limb(m,hx,1.45,kx,ky,.24,hz,.2,coat)
  M.limb(m,kx,ky,fx,fy,.16,hz,.17,coat)
  M.limb(m,fx,fy,tx,ty,.2,hz,.2,colors.black)
 end
 -- Saddlecloth and a crouched jockey in the horse's racing colours.
 M.box(m,-.5,1.5,-.39,.85,.55,.78,silk)
 M.limb(m,-.25,2.12,.3,1.98,.2,0,.66,colors.white)
 M.limb(m,-.2,2.15,.42,2.55,.4,0,.42,silk)
 M.limb(m,.32,2.45,.8,2.2,.12,0,.56,silk)
 M.box(m,.36,2.56,-.16,.32,.28,.32,silk)
 return m
end
return M
]])

writeFile('derby/server.lua', [[
local config=require('derby.config')
local store=require('derby.store')
local house=require('derby.house')
local service=require('derby.service')
local ledger=require('derby.ledger')
local ui=require('derby.ui')
local M={}
function M.run(c)
 config.network(c)
 local initial=house.new(require('derby.odds')); initial.paused=true
 local db=store.open('/house-bank/state',initial)
 local host=service.new(db,c,peripheral.wrap)
 local t=term.current(); local message='P: start after live acceptance. F: recognise funded bank.'
 local function draw()
  local s=host:state(); ui.clear(t,'HOUSE HOST | ID '..os.getComputerID())
  ui.line(t,3,' Bank: '..s.bank..' credits backing | Available: '..ledger.available(s))
  ui.line(t,5,' '..(s.paused and 'PAUSED' or 'RUNNING')..' | '..(s.race and s.race.id..' '..s.race.phase or 'Awaiting first race'))
  ui.line(t,7,' [P] Pause/start  [C] Cancel unstarted race')
  ui.line(t,9,' [F] Recognise added stock  [M] Apply currency config')
  ui.line(t,11,' [R] Reconcile transfer  [U] Refund interrupted game')
  local y=13
  for id,p in pairs(s.pending) do ui.line(t,y,' PENDING '..id..' '..p.kind..' '..tostring(p.requestedItems or p.amount)); y=y+1 end
  for id,r in pairs(s.rounds) do if r.status=='open' and r.game~='derby' then ui.line(t,y,' OPEN '..id..' '..r.game); y=y+1 end end
  local _,h=t.getSize(); ui.line(t,h-1,message,colors.yellow); ui.line(t,h,' [Q] Stop host (all clients go offline)')
 end
 local timer=os.startTimer(.1); draw()
 while true do
  local e,a,b,p=os.pullEvent()
  if e=='timer' and a==timer then
   host:tick(os.epoch('utc')%2147483646); timer=os.startTimer(.1); draw()
  elseif e=='rednet_message' and p=='pine-derby-house-v1' and type(b)=='table' and type(b.token)=='string' then
   local role=c.clients[tostring(a)]
   local result=role and host:request(b.request,role,a) or {ok=false,error='Computer not registered at house host'}
   rednet.send(a,{token=b.token,result=result},p)
  elseif e=='key' then
   local result
   if a==keys.q then return
   elseif a==keys.p then result=host:operator('pause')
   elseif a==keys.c then result=host:operator('cancel')
   elseif a==keys.m then result=host:operator('currency')
   elseif a==keys.f then result=host:operator('fund')
   elseif a==keys.r or a==keys.u then
    t.setCursorPos(1,15); t.clearLine(); write(a==keys.r and 'Transaction ID: ' or 'Round ID: '); local id=read()
    if a==keys.r then write('Verified items actually moved: '); result=host:operator('reconcile',id,tonumber(read()))
    else result=host:operator('refund',id) end
   end
   if result then message=result.ok and 'Saved and verified' or result.error; draw() end
  end
 end
end
return M
]])

writeFile('derby/service.lua', [[
local store=require('derby.store')
local ledger=require('derby.ledger')
local house=require('derby.house')
local inventory=require('derby.inventory')
local currency=require('derby.currency')
local M={}
function M.new(storage,config,wrap)
 local s=storage:get()
 assert(s.version==1 or s.version==2,'Unsupported saved ledger version; restore compatible runtime/state offline')
 -- Reconstruct exact floating-point state instead of trusting JSON-rounded positions.
 if s.race and s.race.sim then
  local sim=require('derby.sim')
  assert(s.race.sim.version==sim.version,'Saved race requires its original simulation version')
  local restored=sim.new(s.race.seed)
  for _=1,s.race.sim.tick do sim.step(restored) end
  s.race.sim=restored
 end
 if s.version==2 then
  assert(config.bank~=config.intake and config.bank~=config.payout and config.intake~=config.payout,'Currency inventories must be distinct')
  currency.validate(s.currency)
  assert(s.bank==currency.value(s.currency,s.stock),'Saved currency stock/value mismatch')
  assert(ledger.available(s)>=0,'Saved currency ledger is unbacked')
 end
 local api={}
 local function stock(name) return inventory.stock(assert(wrap(name),'Inventory unavailable: '..tostring(name)),s.currency) end
 local function same(a,b) return currency.canonical(a)==currency.canonical(b) end
 local function observations()
  return {bank=stock(config.bank),intake=stock(config.intake),payout=stock(config.payout)}
 end
 local function verifiedMovement(p,moved)
  local now=observations(); local expected=store.copy(p.observed)
  local source=p.kind=='deposit' and 'intake' or 'bank'
  local dest=p.kind=='deposit' and 'bank' or 'payout'
  expected[source][p.entryId]=(expected[source][p.entryId] or 0)-moved
  expected[dest][p.entryId]=(expected[dest][p.entryId] or 0)+moved
  assert(same(now,expected),'Classified inventory deltas differ; isolate inventories and reconcile')
 end
 local function commit(nextState)
  storage:save(nextState); s=nextState
 end
 local function denied(message) return {ok=false,error=message} end
 function api:state() return store.copy(s) end
 function api:request(q,role,owner)
  if type(q)~='table' or type(q.op)~='string' then return denied('Invalid request') end
  if q.op=='currency' then return {ok=true,apiVersion=s.version,policy=s.version==2 and store.copy(s.currency) or nil} end
  if q.op=='snapshot' then return house.snapshot(s,q.account) end
  if q.op=='lookup' or q.op=='status' or q.op=='roundStatus' then return ledger.apply(s,q) end
  if role=='display' then return denied('Display is read only') end
  if type(q.id)~='string' or not q.id:match('^'..tostring(owner)..':') then return denied('Wrong transaction owner') end
  if q.op=='create' or q.op=='deposit' or q.op=='withdraw' or q.op=='exchange' then
   if role~='cashier' then return denied('Cashier operation') end
  elseif q.op~='bet' and q.op~='reserve' and q.op~='increase' and q.op~='settle' and q.op~='refund' then return denied('Operation not available remotely') end
  local nextState=store.copy(s)
  local request=store.copy(q); request.owner=tostring(owner)
  -- A repeated transfer must return its receipt without touching inventories again.
  local existed=nextState.transactions[request.id]~=nil
  local observed
  if request.op=='exchange' and not existed then
   if s.version~=2 then return denied('Migrate host currency before using API 2') end
   local ok,value=pcall(observations)
   if not ok then return denied('Cannot classify inventories: '..tostring(value)) end
   observed=value
   if not same(observed.bank,s.stock) then return denied('Classified bank stock differs; reconcile before transfer') end
  end
  local result=request.op=='bet' and house.bet(nextState,request) or ledger.apply(nextState,request)
  if not result.ok then return result end
  if observed and result.pending then
   local p=nextState.pending[q.id]; p.observed=observed
   p.source=q.direction=='deposit' and config.intake or config.bank
   p.destination=q.direction=='deposit' and config.bank or config.payout
  end
  commit(nextState)
  if q.op=='exchange' and not existed then
   local p=s.pending[q.id]
   local ok,moved=pcall(function()
    assert(same(observations(),p.observed),'Inventories changed since durable intent')
    local count=inventory.move(assert(wrap(p.source)),p.destination,p.requestedItems,p.entry)
    verifiedMovement(p,count)
    return count
   end)
   if not ok then return {ok=false,pending=true,error='Transfer uncertain; operator reconciliation required: '..tostring(moved)} end
   nextState=store.copy(s); local receipt=ledger.complete(nextState,q.id,moved); commit(nextState); return receipt
  end
  if (q.op=='deposit' or q.op=='withdraw') and not existed then
   -- Intent is durable before either physical side effect.
   local ok,moved=pcall(function()
    local bank=assert(wrap(config.bank),'Bank unavailable')
    assert(inventory.count(bank)==s.bank,'Bank count differs from ledger; reconcile before transfer')
    if q.op=='deposit' then return inventory.move(assert(wrap(config.intake)),config.bank,q.amount) end
    return inventory.move(bank,config.payout,q.amount)
   end)
   if not ok then return denied('Transfer uncertain; operator reconciliation required: '..tostring(moved)) end
   nextState=store.copy(s)
   local receipt=ledger.complete(nextState,q.id,moved)
   commit(nextState)
   return receipt
  end
  return result
 end
 function api:tick(seed)
  local n=store.copy(s); house.tick(n,seed)
  -- Save every second and every phase boundary. Replayed sub-second steps use the saved RNG.
  local boundary=not s.race or (n.race and n.race.phase~=s.race.phase)
  if boundary or (n.race and n.race.elapsed%10==0) then commit(n) else s=n end
 end
 function api:operator(op,id,amount)
  local n=store.copy(s)
  if op=='currency' then
   if config.bank==config.intake or config.bank==config.payout or config.intake==config.payout then return denied('Currency inventories must be distinct') end
   if not s.paused or next(s.pending) then return denied('Pause host and reconcile pending transfers first') end
   local policy=config.currency or currency.default()
   local ok,value=pcall(function()
    currency.validate(policy)
    local bank=assert(wrap(config.bank))
    if s.version==1 then assert(inventory.count(bank)==s.bank,'Legacy bank count differs; reconcile before migration') end
    return ledger.changeCurrency(s,policy,inventory.stock(bank,policy))
   end)
   if not ok then return denied(tostring(value)) end
   storage:changeCurrency(value); s=value; return {ok=true}
  elseif op=='pause' then n.paused=not n.paused
  elseif op=='cancel' then local r=house.cancel(n); if not r.ok then return r end
  elseif op=='fund' then
   if next(n.pending) then return denied('Reconcile pending transfer first') end
   if s.version==2 then
    local classified=stock(config.bank)
    for key,count in pairs(s.stock) do if (classified[key] or 0)<count then return denied('Bank item shortage; restore missing stock') end end
    n.stock=classified; n.bank=currency.value(s.currency,classified)
    if n.bank>1000000000 then return denied('Bank value exceeds supported credit limit') end
    if ledger.available(n)<0 then return denied('Bank cannot cover liabilities') end
    commit(n); return {ok=true}
   end
   local count=inventory.count(assert(wrap(config.bank)))
   if count<n.bank then return denied('Bank shortage: restore missing diamonds before continuing') end
   local r=ledger.apply(n,{op='fund',id='fund:'..tostring(os.epoch('utc')),amount=count}); if not r.ok then return r end
  elseif op=='reconcile' then
   local p=n.pending[id]; if not p then return denied('No such pending transfer') end
   if s.version==2 then
    if type(amount)~='number' or amount%1~=0 or amount<0 or amount>p.requestedItems then return denied('Invalid moved item count') end
    if p.source~=(p.kind=='deposit' and config.intake or config.bank) or p.destination~=(p.kind=='deposit' and config.bank or config.payout) then return denied('Restore original inventory configuration before reconciliation') end
    local ok,err=pcall(verifiedMovement,p,amount); if not ok then return denied(tostring(err)) end
    ledger.complete(n,id,amount); commit(n); return {ok=true}
   end
   if type(amount)~='number' or amount%1~=0 or amount<0 or amount>p.amount then return denied('Invalid moved amount') end
   local expected=p.beforeBank+(p.kind=='deposit' and amount or -amount)
   if inventory.count(assert(wrap(config.bank)))~=expected then return denied('Count does not match bank; inspect intake/output and restore consistency') end
   ledger.complete(n,id,amount)
  elseif op=='refund' then
   local r=n.rounds[id]
   if not r or r.status~='open' or r.game=='derby' then return denied('No interrupted arcade round with this ID') end
   local result=ledger.apply(n,{op='refund',id='operator-refund:'..id,round=id,account=r.account,owner=r.owner})
   if not result.ok then return result end
  else return denied('Unknown operator action') end
  commit(n); return {ok=true}
 end
 return api
end
return M
]])

writeFile('derby/sfx.lua', [[
-- Race-day sound for the display and the betting station. Notes go through casino.sound,
-- which holds them until the frame loop plays them, so sound never sleeps the event loop.
-- Times are milliseconds on os.epoch('utc'); the caller passes `now` and ticks the queue.
local M={}
local GALLOP=450
local PLACES={24,19,14}
function M.new(sound)
 local self={sound=sound or require('casino.sound')(),phase=nil,second=nil,placed=0,gallopAt=0}
 local function note(at,instrument,volume,pitch) self.sound:play(at,instrument,volume,pitch) end
 -- The display calls this with every snapshot. Joining mid-race stays quiet until a
 -- phase change is actually seen, so only real starts and finishes get fanfares.
 function self:hear(v,now)
  local phase=v.phase
  if phase~=self.phase then
   local was=self.phase
   if phase=='RUNNING' and was=='LOCKED' then
    for i,p in ipairs({12,16,19,24}) do note(now+(i-1)*90,'bell',1.2,p) end
    note(now,'snare',1.2,12); note(now,'basedrum',1.2,8)
    self.gallopAt=now+500
   elseif phase=='RESULT' and was=='RUNNING' then
    for i,p in ipairs({12,16,19,24,19,24}) do note(now+400+(i-1)*130,'bell',1,p) end
    note(now+1100,'chime',1,24)
   elseif phase=='CANCELLED' then
    note(now,'bass',1,8); note(now+150,'bass',1,4); note(now+300,'bass',1,0)
   end
   self.phase=phase; self.second=nil; self.placed=#(v.order or {})
  end
  if phase=='LOCKED' and v.seconds and v.seconds>0 and v.seconds~=self.second then
   self.second=v.seconds
   if v.seconds<=3 then note(now,'pling',1,12+(3-v.seconds)*4) else note(now,'hat',.6,18) end
  end
  if phase=='RUNNING' then
   if now>=self.gallopAt then
    self.gallopAt=now+GALLOP
    note(now,'basedrum',.6,3); note(now+110,'hat',.5,10); note(now+220,'hat',.5,10)
   end
   local order=v.order or {}
   while self.placed<#order do
    self.placed=self.placed+1
    note(now,'bell',1.2,PLACES[self.placed] or 12); note(now,'snare',.8,16)
   end
  end
  self.sound:tick(now)
 end
 -- Betting station feedback.
 function self:move(now) note(now,'hat',.4,20); self.sound:tick(now) end
 function self:ticket(accepted,now)
  if accepted then note(now,'bell',1,12); note(now+100,'bell',1,16); note(now+200,'bell',1,19)
  else note(now,'bass',1,6); note(now+120,'bass',1,3) end
  self.sound:tick(now)
 end
 function self:tick(now) self.sound:tick(now) end
 return self
end
return M
]])

writeFile('derby/sim.lua', [[
-- Pure, versioned simulation. Distances and time do not depend on the renderer.
local M = { version = 1, dt = .1, distance = 450 }
M.horses = {
 {name="COPPER COMET", style="STEADY", color=2},
 {name="LEDGER LIZARD", style="CLOSER", color=256},
 {name="NEON PANIC", style="CHAOS", color=1024},
}
local function random(s)
 s.rng = (s.rng * 48271) % 2147483647
 return s.rng / 2147483647
end
function M.new(seed)
 local s={seed=seed, rng=math.floor(seed)%2147483646+1, tick=0, horses={}, order={}, version=M.version}
 for _=1,8 do random(s) end
 for i=1,3 do s.horses[i]={distance=0, ability=.88+random(s)*.24, surge=0} end
 return s
end
function M.step(s)
 if #s.order == 3 then return s end
 s.tick=s.tick+1
 local crossing={}
 for i,h in ipairs(s.horses) do
  if not h.finish then
   local p=h.distance/M.distance
   local r=random(s)
   local speed
   if i==1 then speed=.95+r*.12
   elseif i==2 then speed=.82+.36*p+(r-.5)*.2
   else speed=.99+(r-.5)*1.6; if r>.97 then speed=2.5 elseif r<.04 then speed=0 end end
   if s.tick%25==1 then h.surge=(random(s)-.5)*.25 end
   speed=math.max(.03,(speed+h.surge)*h.ability)
   local previous=h.distance
   h.distance=previous+speed
   if h.distance>=M.distance then
    h.finish=(s.tick-1+(M.distance-previous)/speed)*M.dt
    crossing[#crossing+1]={id=i,time=h.finish,tie=random(s)}
   end
  end
 end
 table.sort(crossing,function(a,b) if a.time==b.time then return a.tie<b.tie end return a.time<b.time end)
 for _,c in ipairs(crossing) do s.order[#s.order+1]=c.id end
 return s
end
function M.run(seed)
 local s=M.new(seed)
 while #s.order<3 do M.step(s) end
 return s
end
function M.positions(s)
 local out={}
 for i,h in ipairs(s.horses) do out[i]=math.min(1,h.distance/M.distance) end
 return out
end
return M
]])

writeFile('derby/station.lua', [[
local ui=require('derby.ui')
local sim=require('derby.sim')
local M={}
function M.run(client,t)
 local horse,stakeIndex,focus=1,1,1
 local stakes={5,10,20}; local status=''; local review
 local snapshot={}; local account,balance,card
 local timer=os.startTimer(0)
 local sfx=require('derby.sfx').new()
 local tone=os.startTimer(.1)
 local function refresh()
  card=ui.card(); account=card and card.account
  local r=client:read({op='snapshot',account=account})
  snapshot=r
  if account then local a=client:read({op='lookup',account=account}); balance=a.ok and a.balance or nil; if not a.ok then status=a.error end else balance=nil end
 end
 local function draw()
  if not ui.usable(t) then return end
  ui.clear(t,'DERBY BETTING')
  ui.line(t,2,account and (' Balance: '..tostring(balance or 'UNAVAILABLE')..' credits') or ' Insert a house account card',colors.yellow)
  if review then
   ui.line(t,4,' CONFIRM YOUR TICKET',colors.yellow)
   ui.line(t,6,' '..review.horse..' '..sim.horses[review.horse].name)
   ui.line(t,8,' Stake: '..review.stake..' credits')
   ui.line(t,10,' Total return if winner: '..review.returns)
   ui.line(t,11,' Includes your stake | 1 credit = 1 diamond')
   ui.button(t,13,'ENTER: PLACE BET',true,false)
   ui.line(t,17,' Backspace: back | Q: exit')
  else
   ui.line(t,3,snapshot.ok and (' '..tostring(snapshot.phase)..' | '..tostring(snapshot.seconds or 0)..'s'..(snapshot.paused and ' | PAUSED' or '')) or ' HOUSE OFFLINE - BETTING UNAVAILABLE',colors.yellow)
   for i,h in ipairs(sim.horses) do
    local returns=snapshot.payouts and snapshot.payouts[i][tostring(stakes[stakeIndex])]
    ui.button(t,4+(i-1)*3,i..' '..h.name..' | return '..tostring(returns or '--'),focus==i,horse==i)
   end
   ui.line(t,14,(focus==4 and '> ' or '  ')..'Stake: '..stakes[stakeIndex]..'  [Left/Right]',colors.white,focus==4 and colors.blue or colors.black)
   ui.button(t,15,snapshot.ticket and 'TICKET ACCEPTED' or 'REVIEW BET',focus==5,false)
   ui.line(t,18,' Tab/Arrows | Enter | R: retry | Q: exit')
  end
  local w,h=t.getSize(); ui.line(t,h,' '..status,colors.yellow)
 end
 local function activate()
  if not ui.usable(t) then return end
  if review then
   local now=ui.card()
   if not now or now.account~=review.account then status='Card changed. Bet not sent.'; review=nil; return end
   local r=client:mutate({op='bet',account=review.account,race=review.race,horse=review.horse,stake=review.stake})
   status=r.ok and 'Ticket accepted. Winnings reach your account.' or r.error; review=nil; sfx:ticket(r.ok,os.epoch('utc')); refresh()
  elseif focus<=3 then horse=focus
  elseif focus==4 then stakeIndex=stakeIndex%3+1
  elseif snapshot.ok and snapshot.phase=='OPEN' and not snapshot.paused and account and balance and not snapshot.ticket then
   review={account=account,race=snapshot.id,horse=horse,stake=stakes[stakeIndex],returns=snapshot.payouts[horse][tostring(stakes[stakeIndex])]}
  else status='Bet unavailable: check card, host and race status.' end
 end
 draw()
 while true do
  local e,a,b,c=os.pullEvent()
  if e=='timer' and a==timer then refresh(); timer=os.startTimer(1)
  elseif e=='timer' and a==tone then sfx:tick(os.epoch('utc')); tone=os.startTimer(.1)
  elseif e=='key' then
   if a==keys.q then return
   elseif a==keys.r then local r=client:retry(); status=r.ok and 'Request acknowledged' or r.error; refresh()
   elseif a==keys.backspace then review=nil
   elseif a==keys.enter then activate()
   elseif not review then
    local moved=true
    if a==keys.tab or a==keys.down then focus=focus%5+1 elseif a==keys.up then focus=(focus-2)%5+1
    elseif a==keys.left then stakeIndex=(stakeIndex-2)%3+1 elseif a==keys.right then stakeIndex=stakeIndex%3+1
    else moved=false end
    if moved then sfx:move(os.epoch('utc')) end
   end
  elseif e=='monitor_touch' or e=='mouse_click' then
   local y=c
   if review and y>=13 and y<=15 then activate()
   elseif not review then
    if y>=4 and y<=12 then focus=math.floor((y-4)/3)+1; activate()
    elseif y==14 then focus=4; activate()
    elseif y>=15 and y<=17 then focus=5; activate() end
   end
  end
  draw()
 end
end
return M
]])

writeFile('derby/store.lua', [[
-- Two generation slots: interrupted writes leave the previous committed state.
local M={}
local function checksum(s)
 local n=0
 for i=1,#s do n=(n*31+s:byte(i))%2147483647 end
 return n
end
function M.copy(t)
 if type(t)~='table' then return t end
 local out={}; for k,v in pairs(t) do out[M.copy(k)]=M.copy(v) end
 return out
end
function M.open(base, initial)
 local seq=0
 local state,selectedChecksum
 local seen=false
 for slot=0,1 do
  local path=base..'.'..slot
  if fs.exists(path) then
   seen=true
   local f=fs.open(path,'r'); local data=f and f.readAll(); if f then f.close() end
   local ok,v=pcall(textutils.unserializeJSON,data or '')
   if ok and type(v)=='table' and type(v.payload)=='string' and type(v.seq)=='number' and checksum(v.payload)==v.checksum then
    local good,p=pcall(textutils.unserializeJSON,v.payload)
    if good and type(p)=='table' and v.seq>seq then state=p; seq=v.seq; selectedChecksum=checksum(v.payload) end
   end
  end
 end
 assert(state or not seen,'Both saved state slots are invalid; restore backup. No new bank was created.')
 state=state or M.copy(initial)
 local marker=base..'.currency-version'
 if fs.exists(marker) then
  local f=assert(fs.open(marker,'r')); local floor=textutils.unserializeJSON(f.readAll()); f.close()
  assert(type(floor)=='table' and floor.version==2
   and type(floor.revision)=='number' and floor.revision>=1 and floor.revision%1==0
   and type(floor.seq)=='number' and floor.seq>=0 and floor.seq%1==0
   and type(floor.checksum)=='number' and floor.checksum==selectedChecksum
   and state.version==2 and state.currency and state.currency.revision==floor.revision and seq==floor.seq,
   'Currency generation guard mismatch; restore verified versioned backup offline')
 end
 assert(state.version~=2 or fs.exists(marker),'Version 2 currency generation guard missing; offline recovery required')
 local api={}
 function api:get() return M.copy(state) end
 function api:save(value)
  local payload=textutils.serializeJSON(M.copy(value))
  if value.version==2 then
   -- A v2 generation rollback could erase an intent and replay physical movement.
   -- Persist a fail-closed floor BEFORE every generation write. Interrupted writes
   -- may require offline recovery, but never silently revive an older receipt.
   local boundary=textutils.serializeJSON({version=2,revision=value.currency.revision,seq=seq+1,checksum=checksum(payload)})
   fs.makeDir(fs.getDir(base))
   local guard=assert(fs.open(marker,'w')); guard.write(boundary); guard.close()
   guard=assert(fs.open(marker,'r')); local actual=guard.readAll(); guard.close()
   assert(actual==boundary,'Currency generation guard readback failed')
  end
  local path=base..'.'..((seq+1)%2)
  fs.makeDir(fs.getDir(base))
  local f=assert(fs.open(path,'w'),'Cannot persist '..path)
  f.write(textutils.serializeJSON({seq=seq+1,payload=payload,checksum=checksum(payload)})); f.close()
  local verify=assert(fs.open(path,'r')); local disk=textutils.unserializeJSON(verify.readAll()); verify.close()
  assert(disk and disk.seq==seq+1 and disk.payload==payload and disk.checksum==checksum(payload),'Persistence readback failed')
  seq=seq+1; state=M.copy(value)
 end
 function api:changeCurrency(value)
  assert(value.version==2,'Expected version 2 currency state')
  -- Preserve both exact old generations before changing the interpretation of bank.
  local tag=state.version==2 and ('v2-r'..state.currency.revision) or 'v1'
  for slot=0,1 do
   local source=base..'.'..slot
   if fs.exists(source) then
    local f=assert(fs.open(source,'r')); local bytes=f.readAll(); f.close()
    local target=base..'.backup-'..tag..'.'..slot
    if fs.exists(target) then
     f=assert(fs.open(target,'r')); local old=f.readAll(); f.close()
     assert(old==bytes,'Existing migration backup differs; archive it offline before retry')
    else
     f=assert(fs.open(target,'w')); f.write(bytes); f.close()
     f=assert(fs.open(target,'r')); local verified=f.readAll(); f.close(); assert(verified==bytes,'Backup readback failed')
    end
   end
  end
  fs.makeDir(fs.getDir(base))
  local f=assert(fs.open(marker,'w')); local boundary=textutils.serializeJSON({version=2,revision=value.currency.revision}); f.write(boundary); f.close()
  f=assert(fs.open(marker,'r')); local verified=f.readAll(); f.close(); assert(verified==boundary,'Version marker readback failed')
  -- Both generations must use the new interpretation before restart fallback is safe.
  self:save(value); self:save(value)
 end
 return api
end
return M
]])

writeFile('derby/ui.lua', [[
local M={}
function M.line(t,y,text,fg,bg)
 local w,h=t.getSize(); if y<1 or y>h then return end
 t.setCursorPos(1,y); t.setTextColor(fg or colors.white); t.setBackgroundColor(bg or colors.black)
 t.write((tostring(text)..string.rep(' ',w)):sub(1,w))
end
function M.clear(t,title)
 require('derby.palette').apply(t)
 t.setBackgroundColor(colors.black); t.setTextColor(colors.white); t.clear()
 M.line(t,1,' '..title,colors.white,colors.blue)
end
function M.button(t,y,label,focused,selected)
 local w=t.getSize(); local bg=focused and colors.white or colors.gray; local fg=focused and colors.black or colors.white
 local prefix=(focused and '> ' or '  ')..(selected and '[X] ' or '[ ] ')
 for row=y,y+2 do M.line(t,row,row==y+1 and prefix..label or '',fg,bg) end
 return {y=y,height=3}
end
