        elseif sel == "fortune" then desc = "Chance for 2x clicks"
        elseif sel == "haste" then desc = "Worker speed +20%"
        elseif sel == "mending" then desc = "Passive +0.5/s"
        elseif sel == "unbreaking" then desc = "Costs -5% (min 50%)"
        end
    end
    writeAt(2, h - 2, desc, colors.gray, colors.black)

    drawButtonBar("Back", "Install", "Next")
end

local function buyMod(modKey)
    local cost = getModCost(modKey)
    if state.blocks >= cost then
        state.blocks = state.blocks - cost
        state.mods[modKey] = (state.mods[modKey] or 0) + 1
        audio.play("click")
        return true
    end
    return false
end

--------------------------------------------------------------------------------
-- ATTRACT MODE / DEMO
--------------------------------------------------------------------------------

local function drawDemo()
    refreshSize()
    term.setBackgroundColor(colors.black)
    term.clear()

    -- Title
    local title = "IDLECRAFT"
    writeAt(cx - #title/2, 3, title, colors.lime, colors.black)

    -- Subtitle
    local sub = "Minecraft Incremental"
    writeAt(cx - #sub/2, 4, sub, colors.green, colors.black)

    -- Animation: falling blocks
    local blocks = { "\127", "#", "O", "@", "*" }
    for i = 1, 8 do
        local bx = math.random(2, w - 1)
        local by = math.random(6, h - 4)
        local bc = { colors.brown, colors.gray, colors.lightGray, colors.cyan }
        writeAt(bx, by, blocks[math.random(#blocks)], bc[math.random(#bc)], colors.black)
    end

    -- Features
    local y = 8
    writeAt(4, y, "\7 Hire Steves & Alexes", colors.white, colors.black)
    writeAt(4, y + 1, "\7 Build Mines & Forges", colors.white, colors.black)
    writeAt(4, y + 2, "\7 Install Enchantment Mods", colors.white, colors.black)
    writeAt(4, y + 3, "\7 Prestige for Bonuses", colors.white, colors.black)

    -- Free to play
    writeAt(cx - 7, h - 3, "FREE TO PLAY!", colors.yellow, colors.black)

    drawButtonBar("", "Play", "")
end

local function runDemo()
    local demoTimer = os.startTimer(5)

    while true do
        drawDemo()

        local e, p1 = os.pullEvent()

        if e == "timer" and p1 == demoTimer then
            return false  -- Demo ended, go back to menu
        end

        local button = input.getButton(e, p1)
        if button then
            return true  -- Player wants to play
        end
    end
end

--------------------------------------------------------------------------------
-- MAIN GAME LOOP
--------------------------------------------------------------------------------

local function waitInput(timeout)
    local timer = timeout and os.startTimer(timeout) or nil

    while true do
        local e, p1 = os.pullEvent()

        if e == "timer" then
            if p1 == timer then
                return nil, "tick"
            end
        end

        local button = input.getButton(e, p1)
        if button then
            if e == "redstone" then sleep(0.1) end
            return button
        end
    end
end

local function gameLoop()
    loadGame()
    state.lastTick = os.clock()

    local saveTimer = 0
    local running = true

    while running do
        -- Calculate time delta
        local now = os.clock()
        local dt = now - state.lastTick
        state.lastTick = now

        -- Game tick
        doTick(dt)

        -- Draw current menu
        if currentMenu == "main" then
            drawMainMenu()
        elseif currentMenu == "shop" then
            drawShopMenu()
        elseif currentMenu == "mods" then
            drawModMenu()
        end

        -- Autosave every ~30 seconds of game time
        saveTimer = saveTimer + dt
        if saveTimer >= 30 then
            saveGame()
            saveTimer = 0
        end

        -- Wait for input with timeout for ticks
        local button, reason = waitInput(0.5)

        if button then
            if currentMenu == "main" then
                if button == "LEFT" then
                    currentMenu = "shop"
                    menuSelection = 1
                elseif button == "CENTER" then
                    doClick()
                elseif button == "RIGHT" then
                    currentMenu = "mods"
                    menuSelection = 1
                end

            elseif currentMenu == "shop" then
                if button == "LEFT" then
                    currentMenu = "main"
                elseif button == "CENTER" then
                    local item = shopItems[menuSelection]
                    buyItem(item.key)
                elseif button == "RIGHT" then
                    menuSelection = menuSelection + 1
                    if menuSelection > #shopItems then
                        menuSelection = 1
                    end
                end

            elseif currentMenu == "mods" then
                if button == "LEFT" then
                    currentMenu = "main"
                elseif button == "CENTER" then
                    if menuSelection <= #modItems then
                        buyMod(modItems[menuSelection])
                    end
                elseif button == "RIGHT" then
                    menuSelection = menuSelection + 1
                    if menuSelection > #modItems then
                        menuSelection = 1
                    end
                end
            end
        end
    end

    saveGame()
end

--------------------------------------------------------------------------------
-- ENTRY POINT
--------------------------------------------------------------------------------

local programArgs = { ... }

local function main()
    math.randomseed(os.time())

    -- Check for demo mode (attract mode from menu)
    local args = programArgs
    if args[1] == "--demo" then
        while true do
            local wantsPlay = runDemo()
            if wantsPlay then
                break
            end
            return  -- Exit back to menu
        end
    end

    -- Run main game
    gameLoop()
end

-- Handle graceful exit
local ok, err = pcall(main)
saveGame()

if not ok and err ~= "Terminated" then
    term.setBackgroundColor(colors.black)
    term.setTextColor(colors.red)
    print("Error: " .. tostring(err))
    sleep(2)
end

term.setBackgroundColor(colors.black)
term.clear()
term.setCursorPos(1, 1)
]])

writeFile('input.lua', [[
-- input.lua
-- Input handling for Arcade OS

local config = {
    LEFT = { type = "key", value = keys.left },
    CENTER = { type = "key", value = keys.up },
    RIGHT = { type = "key", value = keys.right }
}

-- Load config if exists
if fs.exists(".button_config") then
    local file = fs.open(".button_config", "r")
    if file then
        local data = file.readAll()
        file.close()
        local loaded = textutils.unserialize(data)
        if loaded then
            config = loaded
        end
    end
end

-- Also support default keys for keyboard fallback
local DEFAULT_KEYS = {
    LEFT = { keys.left, keys.a, keys.q },
    CENTER = { keys.up, keys.w, keys.space, keys.enter },
    RIGHT = { keys.right, keys.d, keys.e }
}

local function isKey(key, set)
    for _, k in ipairs(set) do
        if key == k then return true end
    end
    return false
end

-- Track last-known redstone states so we can detect which button was pressed
-- on the rising edge (helps when multiple inputs are momentarily high).
local lastRedstone = {
    LEFT = false,
    CENTER = false,
    RIGHT = false
}

local function getButton(event, p1)
    if event == "key" then
        -- Check configured keys
        if config.LEFT.type == "key" and p1 == config.LEFT.value then return "LEFT" end
        if config.CENTER.type == "key" and p1 == config.CENTER.value then return "CENTER" end
        if config.RIGHT.type == "key" and p1 == config.RIGHT.value then return "RIGHT" end

        -- Check default keys (fallback/keyboard support)
        if isKey(p1, DEFAULT_KEYS.LEFT) then return "LEFT" end
        if isKey(p1, DEFAULT_KEYS.CENTER) then return "CENTER" end
        if isKey(p1, DEFAULT_KEYS.RIGHT) then return "RIGHT" end

    elseif event == "char" then
        -- Numeric keyboard fallback matching on-screen prompts
        local c = tostring(p1 or "")
        if c == "1" then return "LEFT" end
        if c == "2" then return "CENTER" end
        if c == "3" then return "RIGHT" end

    elseif event == "redstone" then
        -- Prefer configured redstone using rising-edge detection.
        local states = {
            LEFT = (config.LEFT.type == "redstone") and redstone.getInput(config.LEFT.value) or false,
            CENTER = (config.CENTER.type == "redstone") and redstone.getInput(config.CENTER.value) or false,
            RIGHT = (config.RIGHT.type == "redstone") and redstone.getInput(config.RIGHT.value) or false
        }

        local candidates = {}
        for name, now in pairs(states) do
            if now and not lastRedstone[name] then
                table.insert(candidates, name)
            end
        end

        -- Update memory before returning
        lastRedstone.LEFT = states.LEFT
        lastRedstone.CENTER = states.CENTER
        lastRedstone.RIGHT = states.RIGHT

        if #candidates == 1 then
            return candidates[1]
        end
        if #candidates > 1 then
            -- Ambiguous press (multiple lines rose at once). Ignore.
            return nil
        end

        -- Default redstone fallback (Legacy support)
        -- Only check if NOT configured as redstone to avoid double counting if config matches default
        if config.LEFT.type ~= "redstone" and redstone.getInput("left") then return "LEFT" end
        if config.RIGHT.type ~= "redstone" and redstone.getInput("right") then return "RIGHT" end
        if config.CENTER.type ~= "redstone" and (redstone.getInput("top") or redstone.getInput("front")) then return "CENTER" end
    end
    return nil
end

return {
    getButton = getButton
}
]])

