    -- Menu items
    local startY = 5
    local maxVisible = h - 7
    local offset = 0

    -- Scroll if needed
    if selected > maxVisible then
        offset = selected - maxVisible
    end

    for i, item in ipairs(menuItems) do
        local displayIdx = i - offset
