-- Multi-seat tables: one table computer runs the game, 1-4 seat computers play it.
require('tables.app').run({...})
]])

writeFile('track.lua', [[
-- track.lua
-- Track & Field Demake (Timing Race)
-- Controls: [Left]=Player 1, [Center]=Player 2, [Right]=Player 3
-- Time your press in the GREEN zone to advance! RED = go back!
-- Keyboard exit: [Backspace] or [E]

local input = require("input")
local creditsAPI = require("credits")
local audio = require("audio")

math.randomseed(os.epoch("utc"))

local w, h = term.getSize()

--------------------------------------------------------------------------------
-- CONFIG
--------------------------------------------------------------------------------

local BET_COST = 5
local TRACK_LENGTH = math.max(10, h - 8)  -- Vertical track
local WIN_PRIZE = 15

-- Timing bar settings
local BAR_WIDTH = 20
local BAR_SPEED_MIN = 0.03
local BAR_SPEED_MAX = 0.08
local GREEN_SIZE = 4       -- Size of the "sweet spot"
local YELLOW_SIZE = 2      -- Near-miss zone
local RED_SIZE = 2         -- Penalty zone on edges

-- Player config
local players = {
    { name = "P1", color = colors.red, pos = 1, barPos = 1, barDir = 1, barSpeed = 0.05 },
    { name = "P2", color = colors.blue, pos = 1, barPos = 1, barDir = 1, barSpeed = 0.05 },
    { name = "P3", color = colors.green, pos = 1, barPos = 1, barDir = 1, barSpeed = 0.05 },
}

--------------------------------------------------------------------------------
-- HELPERS
--------------------------------------------------------------------------------

local function clamp(n, lo, hi)
    if n < lo then return lo end
    if n > hi then return hi end
    return n
end

local function clear(bg)
    term.setBackgroundColor(bg or colors.black)
    term.setTextColor(colors.white)
    term.clear()
    term.setCursorPos(1, 1)
end

local function drawText(x, y, text, fg, bg)
    term.setCursorPos(x, y)
    if fg then term.setTextColor(fg) end
    if bg then term.setBackgroundColor(bg) end
    term.write(text)
end

local function drawCenter(y, text, fg, bg)
    if bg then term.setBackgroundColor(bg) end
    if fg then term.setTextColor(fg) end
    local x = math.max(1, math.floor((w - #text) / 2) + 1)
    term.setCursorPos(x, y)
    term.write(text)
end

local function waitButtonOrExit()
    while true do
        local event, p1 = os.pullEvent()
        local button = input.getButton(event, p1)
        if button then
            if event == "redstone" then sleep(0.2) end
            return button
        end
        if event == "key" then
            local name = keys.getName(p1)
            if name == "backspace" then return "EXIT" end
        elseif event == "char" then
            if tostring(p1):lower() == "e" then return "EXIT" end
        elseif event == "terminate" then
            return "EXIT"
        end
    end
end

local function waitForBreakEvent(seconds)
    local timerId
    if seconds and seconds > 0 then
        timerId = os.startTimer(seconds)
    end

    while true do
        local event, p1 = os.pullEvent()

        if event == "disk" then
            return { type = "disk", event = event, p1 = p1 }
        end

        local button = input.getButton(event, p1)
        if button then
            if event == "redstone" then sleep(0.2) end
            return { type = "button", button = button, event = event, p1 = p1 }
        end

        if event == "key" then
            local name = keys.getName(p1)
            if name == "backspace" then return { type = "exit" } end
            return { type = "key", event = event, p1 = p1 }
        elseif event == "char" then
            if tostring(p1):lower() == "e" then return { type = "exit" } end
            return { type = "key", event = event, p1 = p1 }
        elseif event == "terminate" then
            return { type = "exit" }
        end

        if timerId and event == "timer" and p1 == timerId then
            return { type = "timeout" }
        end
    end
end

--------------------------------------------------------------------------------
-- DRAWING
--------------------------------------------------------------------------------

local function drawHeader(credits)
    term.setBackgroundColor(colors.blue)
    term.setTextColor(colors.white)
    term.setCursorPos(1, 1)
    term.clearLine()

    local title = " TRACK & FIELD "
    term.setCursorPos(math.floor((w - #title) / 2) + 1, 1)
    term.write(title)

    if credits then
        local cStr = "Credits: " .. tostring(credits)
        term.setCursorPos(w - #cStr, 1)
        term.write(cStr)
    end
end

-- Draw timing bar for a player
local function drawTimingBar(player, x, y)
    local barWidth = BAR_WIDTH

    -- Calculate zone positions (centered green zone)
    local greenStart = math.floor((barWidth - GREEN_SIZE) / 2) + 1
    local greenEnd = greenStart + GREEN_SIZE - 1
    local yellowStart = greenStart - YELLOW_SIZE
    local yellowEnd = greenEnd + YELLOW_SIZE

    -- Draw the bar background with zones
    term.setCursorPos(x, y)
    for i = 1, barWidth do
        local bg
        if i <= RED_SIZE or i > barWidth - RED_SIZE then
            bg = colors.red
        elseif i >= greenStart and i <= greenEnd then
            bg = colors.lime
        elseif i >= yellowStart and i <= yellowEnd then
            bg = colors.yellow
        else
            bg = colors.gray
        end
        term.setBackgroundColor(bg)
        term.write(" ")
    end

    -- Draw the moving indicator
    local indicatorPos = math.floor(player.barPos)
    if indicatorPos >= 1 and indicatorPos <= barWidth then
        term.setCursorPos(x + indicatorPos - 1, y)
        term.setBackgroundColor(colors.white)
        term.setTextColor(colors.black)
        term.write("|")
    end

    -- Draw player label
    term.setCursorPos(x - 4, y)
    term.setBackgroundColor(colors.black)
    term.setTextColor(player.color)
    term.write(player.name .. ":")
end

-- Get the zone at a position
local function getZone(pos)
    local barWidth = BAR_WIDTH
    local greenStart = math.floor((barWidth - GREEN_SIZE) / 2) + 1
    local greenEnd = greenStart + GREEN_SIZE - 1
    local yellowStart = greenStart - YELLOW_SIZE
    local yellowEnd = greenEnd + YELLOW_SIZE

    local intPos = math.floor(pos)

    if intPos <= RED_SIZE or intPos > barWidth - RED_SIZE then
        return "RED"
    elseif intPos >= greenStart and intPos <= greenEnd then
        return "GREEN"
    elseif intPos >= yellowStart and intPos <= yellowEnd then
        return "YELLOW"
    else
        return "GRAY"
    end
end

-- Draw the vertical race track
local function drawTrack(startY)
    local trackX = 6
    local trackWidth = #players * 6 + 4

    -- Draw finish line
    term.setCursorPos(trackX, startY)
    term.setBackgroundColor(colors.black)
    term.setTextColor(colors.yellow)
    term.write(string.rep("=", trackWidth) .. " FINISH!")

    -- Draw track lanes
    for row = 1, TRACK_LENGTH do
        local y = startY + row
        term.setCursorPos(trackX, y)
        term.setBackgroundColor(colors.black)
        term.setTextColor(colors.gray)

        -- Lane dividers and runners
        for i, p in ipairs(players) do
            local laneX = trackX + (i - 1) * 6 + 2

            -- Is runner at this position? (invert: pos 1 = bottom, TRACK_LENGTH = top)
            local runnerRow = TRACK_LENGTH - p.pos + 1

            if row == runnerRow then
                -- Draw runner
                term.setCursorPos(laneX, y)
                term.setTextColor(p.color)
                term.setBackgroundColor(colors.black)
                term.write(" o ")   -- Head
            else
                -- Empty lane
                term.setCursorPos(laneX, y)
                term.setBackgroundColor(colors.black)
                term.setTextColor(colors.gray)
                if row == TRACK_LENGTH then
                    term.write("---")  -- Start line
                else
                    term.write(" | ")
                end
            end
        end
    end

    -- Draw start label
    term.setCursorPos(trackX, startY + TRACK_LENGTH + 1)
    term.setBackgroundColor(colors.black)
    term.setTextColor(colors.white)
    term.write(" START " .. string.rep("-", trackWidth - 7))

    -- Draw lane labels
    for i, p in ipairs(players) do
        local laneX = trackX + (i - 1) * 6 + 2
        term.setCursorPos(laneX, startY + TRACK_LENGTH + 2)
        term.setTextColor(p.color)
        term.write(" " .. p.name .. " ")
    end
end

-- Draw instructions
local function drawInstructions(y)
    term.setBackgroundColor(colors.black)
    drawCenter(y, "[1] P1  [2] P2  [3] P3", colors.lightGray)
    drawCenter(y + 1, "Press when indicator is in GREEN!", colors.lime)
end

--------------------------------------------------------------------------------
-- GAME LOGIC
--------------------------------------------------------------------------------

local function resetPlayers()
    for i, p in ipairs(players) do
        p.pos = 1
        p.barPos = 1
        p.barDir = 1
        p.barSpeed = BAR_SPEED_MIN + math.random() * (BAR_SPEED_MAX - BAR_SPEED_MIN)
    end
end

local function updateBars(dt)
    for i, p in ipairs(players) do
        p.barPos = p.barPos + p.barDir * p.barSpeed * dt * 60

        -- Bounce off edges
        if p.barPos >= BAR_WIDTH then
            p.barPos = BAR_WIDTH
            p.barDir = -1
            -- Randomize speed slightly on bounce
            p.barSpeed = BAR_SPEED_MIN + math.random() * (BAR_SPEED_MAX - BAR_SPEED_MIN)
        elseif p.barPos <= 1 then
            p.barPos = 1
            p.barDir = 1
            p.barSpeed = BAR_SPEED_MIN + math.random() * (BAR_SPEED_MAX - BAR_SPEED_MIN)
        end
    end
end

local function handlePress(playerIdx)
    local p = players[playerIdx]
    local zone = getZone(p.barPos)

    if zone == "GREEN" then
        -- Perfect! Move forward 2
        p.pos = clamp(p.pos + 2, 1, TRACK_LENGTH)
        audio.play("advance")
        return "PERFECT", 2
    elseif zone == "YELLOW" then
        -- Good! Move forward 1
        p.pos = clamp(p.pos + 1, 1, TRACK_LENGTH)
        audio.play("advance")
        return "GOOD", 1
    elseif zone == "RED" then
        -- Ouch! Move back 2
        p.pos = clamp(p.pos - 2, 1, TRACK_LENGTH)
        audio.play("bad")
        return "OUCH", -2
    else
        -- Gray zone - no movement
        audio.play("bad")
        return "MISS", 0
    end
end

local function checkWinner()
    for i, p in ipairs(players) do
        if p.pos >= TRACK_LENGTH then
            return i
        end
    end
    return nil
end

local function showResult(playerIdx, result, delta)
    local p = players[playerIdx]
    local msg = p.name .. ": " .. result
    if delta > 0 then
        msg = msg .. " (+" .. delta .. ")"
    elseif delta < 0 then
        msg = msg .. " (" .. delta .. ")"
    end

    local color = colors.white
    if result == "PERFECT" then color = colors.lime
    elseif result == "GOOD" then color = colors.yellow
    elseif result == "OUCH" then color = colors.red
    else color = colors.gray end

    drawCenter(h - 1, msg .. string.rep(" ", 20), color, colors.black)
end

--------------------------------------------------------------------------------
-- MAIN GAME LOOP
--------------------------------------------------------------------------------

local function runRace(cards)
    resetPlayers()

    local barY = 3
    local trackStartY = barY + #players + 2

    -- Calculate dynamic track length
    TRACK_LENGTH = math.max(8, h - trackStartY - 4)

    local lastTime = os.clock()
    local winner = nil

    while not winner do
        local currentTime = os.clock()
        local dt = currentTime - lastTime
        lastTime = currentTime

        -- Update timing bars
        updateBars(dt)

        -- Draw everything
        clear(colors.black)
        drawHeader(cards and cards[1] and creditsAPI.get(cards[1].path))

        -- Draw timing bars
        for i, p in ipairs(players) do
            drawTimingBar(p, 8, barY + i - 1)
        end

        -- Draw track
        drawTrack(trackStartY)

        -- Draw instructions
        drawInstructions(h - 3)

        -- Check for input
        local timerId = os.startTimer(0.05)
        local event, p1 = os.pullEvent()

        if event == "timer" and p1 == timerId then
            -- Just continue animation
        else
            local button = input.getButton(event, p1)

            if button == "LEFT" then
                local result, delta = handlePress(1)
                showResult(1, result, delta)
                sleep(0.15)
            elseif button == "CENTER" then
                local result, delta = handlePress(2)
                showResult(2, result, delta)
                sleep(0.15)
            elseif button == "RIGHT" then
                local result, delta = handlePress(3)
                showResult(3, result, delta)
                sleep(0.15)
            end

            -- Check for exit
            if event == "key" then
                local name = keys.getName(p1)
                if name == "backspace" then return nil end
            elseif event == "char" then
                if tostring(p1):lower() == "e" then return nil end
            elseif event == "terminate" then
                return nil
            end
        end

        winner = checkWinner()
    end

    return winner
end

local function showWinScreen(winnerIdx, cards)
    local p = players[winnerIdx]

    clear(colors.black)
    drawHeader(cards and cards[1] and creditsAPI.get(cards[1].path))

    -- Victory animation
    for flash = 1, 6 do
        local bg = (flash % 2 == 0) and colors.black or p.color
        term.setBackgroundColor(bg)
        term.clear()
        drawHeader(cards and cards[1] and creditsAPI.get(cards[1].path))

        local cy = math.floor(h / 2)
        drawCenter(cy - 2, "================", colors.yellow, bg)
        drawCenter(cy - 1, "    WINNER!     ", colors.white, bg)
        drawCenter(cy, "    " .. p.name .. " WINS!    ", p.color, bg)
        drawCenter(cy + 1, "================", colors.yellow, bg)

        -- ASCII trophy
        drawCenter(cy + 3, "   ___   ", colors.yellow, bg)
        drawCenter(cy + 4, "  |   |  ", colors.yellow, bg)
        drawCenter(cy + 5, "   \\_/   ", colors.yellow, bg)
        drawCenter(cy + 6, "    |    ", colors.yellow, bg)
        drawCenter(cy + 7, "   ===   ", colors.yellow, bg)

        audio.play("win")
        sleep(0.2)
    end

    term.setBackgroundColor(colors.black)
    drawCenter(h - 2, "Press any button to continue...", colors.gray, colors.black)
    waitButtonOrExit()
end

--------------------------------------------------------------------------------
-- ATTRACT MODE
--------------------------------------------------------------------------------

local function runAttractMode()
    resetPlayers()

    local barY = 4
    local trackStartY = barY + #players + 2
    TRACK_LENGTH = math.max(8, h - trackStartY - 4)

    local lastTime = os.clock()
    local autoTimer = 0

    while true do
        local currentTime = os.clock()
        local dt = currentTime - lastTime
        lastTime = currentTime
        autoTimer = autoTimer + dt

        -- Update timing bars
        updateBars(dt)

        -- Auto-play: random button presses
        if autoTimer > 0.3 + math.random() * 0.5 then
            autoTimer = 0
            local idx = math.random(1, 3)
            handlePress(idx)

            -- Check for winner in attract mode, reset if someone wins
            if checkWinner() then
                resetPlayers()
            end
        end

        -- Draw everything
        clear(colors.black)

        term.setBackgroundColor(colors.purple)
        term.setTextColor(colors.white)
        term.setCursorPos(1, 1)
        term.clearLine()
        drawCenter(1, " TRACK & FIELD ", colors.yellow, colors.purple)

        drawCenter(2, "INSERT DISK TO PLAY", colors.white, colors.black)

        -- Draw timing bars
        for i, p in ipairs(players) do
            drawTimingBar(p, 8, barY + i - 1)
        end

        -- Draw track
        drawTrack(trackStartY)

        -- Draw attract text
        drawCenter(h - 2, "Time your press in the GREEN zone!", colors.lime, colors.black)
        drawCenter(h - 1, string.format("Cost: %d credits  |  Prize: %d credits", BET_COST, WIN_PRIZE), colors.gray, colors.black)

        -- Check for break event
        local brk = waitForBreakEvent(0.05)
        if brk then
            if brk.type == "exit" then
                return { type = "exit" }
            elseif brk.type ~= "timeout" then
                return brk
            end
        end
    end
end

--------------------------------------------------------------------------------
-- MAIN ENTRY POINT
--------------------------------------------------------------------------------

local function main()
    while true do
        -- Attract mode until card inserted
        local brk = runAttractMode()

        if brk and brk.type == "exit" then
            clear()
            return
        end

        if brk and brk.type == "disk" then
            -- Card inserted - start game
            local cards = creditsAPI.findCards()

            if #cards > 0 then
                local card = cards[1]
                local currentCredits = creditsAPI.get(card.path)

                if currentCredits >= BET_COST then
                    -- Deduct bet
                    local round, err = creditsAPI.beginRound("track", BET_COST, WIN_PRIZE, card.path)
                    if not round then error("HOUSE: " .. tostring(err), 0) end
                    audio.play("bet")

                    -- Run the race
                    local winner = runRace(cards)

                    creditsAPI.settleRound(round, winner and WIN_PRIZE or 0)
                    creditsAPI.unlock(card.path)
                    if winner then
                        -- Award prize
                        showWinScreen(winner, cards)
                    end
                else
                    -- Not enough credits
                    clear(colors.black)
                    drawHeader(currentCredits)
                    drawCenter(math.floor(h/2), "NOT ENOUGH CREDITS!", colors.red)
                    drawCenter(math.floor(h/2) + 2, string.format("Need %d, have %d", BET_COST, currentCredits), colors.gray)
                    audio.play("bad")
                    sleep(2)
                end
            end
        end
    end
end

-- Run
main()
]])

writeFile('update.lua', [[
-- update.lua
-- Arcade OS Updater
-- Downloads and installs the latest version from the configured URL

local w, h = term.getSize()

-- ============================================================================
-- CONFIGURATION
-- Default update URL points to the official Arcadesys/cc-arcade repo.
-- Override by creating .update_url file with a custom URL.
-- ============================================================================
local UPDATE_URL = "https://raw.githubusercontent.com/Arcadesys/cc-arcade/main/install.lua"

local function centerText(y, text, fg, bg)
    term.setBackgroundColor(bg or colors.black)
    term.setTextColor(fg or colors.white)
    local x = math.floor((w - #text) / 2) + 1
    term.setCursorPos(x, y)
    term.write(text)
end

local function drawHeader()
    term.setBackgroundColor(colors.blue)
    term.setTextColor(colors.yellow)
    term.setCursorPos(1, 1)
    term.clearLine()
    centerText(1, "ARCADE OS UPDATER", colors.yellow, colors.blue)
end

local function readUpdateUrl()
    if UPDATE_URL then return UPDATE_URL end
    if fs.exists(".update_url") then
        local f = fs.open(".update_url", "r")
        if f then
            local url = f.readAll()
            f.close()
            url = (url or ""):gsub("%s+", "")
            if url ~= "" then return url end
        end
    end
    return nil
end

local function saveUpdateUrl(url)
    local f = fs.open(".update_url", "w")
    if f then
        f.write(url)
        f.close()
    end
end

local function promptForUrl()
    term.setBackgroundColor(colors.black)
    term.clear()
    drawHeader()

    centerText(4, "No update URL configured.", colors.yellow, colors.black)
    centerText(6, "Enter the URL to your install.lua:", colors.white, colors.black)
    centerText(7, "(GitHub raw, Pastebin raw, or custom)", colors.gray, colors.black)

    term.setCursorPos(2, 9)
    term.setTextColor(colors.lime)
    term.write("> ")
    term.setTextColor(colors.white)

    local url = read()
    if url and url:match("^https?://") then
        saveUpdateUrl(url)
        return url
    end
    return nil
end

local function downloadInstaller(url)
    term.setBackgroundColor(colors.black)
    term.clear()
    drawHeader()

    centerText(5, "Downloading update...", colors.yellow, colors.black)
    centerText(7, url:sub(1, w - 4), colors.gray, colors.black)

    -- Check if HTTP is enabled
    if not http then
        centerText(10, "ERROR: HTTP is disabled!", colors.red, colors.black)
        centerText(12, "Enable HTTP in ComputerCraft config", colors.white, colors.black)
        centerText(13, "or server settings.", colors.white, colors.black)
        sleep(3)
        return nil
    end

    local response, err = http.get(url)
    if not response then
        centerText(10, "ERROR: Download failed!", colors.red, colors.black)
        centerText(12, tostring(err or "Unknown error"), colors.gray, colors.black)
        sleep(3)
        return nil
    end

    local content = response.readAll()
    response.close()

    if not content or #content < 100 then
        centerText(10, "ERROR: Invalid response!", colors.red, colors.black)
        sleep(3)
        return nil
    end

    return content
end

local function installUpdate(content)
    term.setBackgroundColor(colors.black)
    term.clear()
    drawHeader()

    centerText(5, "Installing update...", colors.yellow, colors.black)

    -- Backup current install.lua
    if fs.exists("install.lua") then
        if fs.exists("install.lua.bak") then
            fs.delete("install.lua.bak")
        end
        fs.copy("install.lua", "install.lua.bak")
    end

    -- Write new installer
    local f = fs.open("install.lua", "w")
    if not f then
        centerText(8, "ERROR: Could not write file!", colors.red, colors.black)
        sleep(3)
        return false
    end
    f.write(content)
    f.close()

    centerText(7, "Running installer...", colors.lime, colors.black)
    sleep(1)

    -- Run the installer
    shell.run("install.lua")
    return true
end

local function showMenu()
    local url = readUpdateUrl()

    term.setBackgroundColor(colors.black)
    term.clear()
    drawHeader()

    centerText(4, "ARCADE OS UPDATE UTILITY", colors.lime, colors.black)

    if url then
        centerText(6, "Update URL:", colors.white, colors.black)
        local displayUrl = #url > w - 6 and url:sub(1, w - 9) .. "..." or url
        centerText(7, displayUrl, colors.gray, colors.black)
    else
        centerText(6, "No update URL configured", colors.yellow, colors.black)
    end

    centerText(10, "[1] Check for Updates", colors.white, colors.black)
    centerText(11, "[2] Configure Update URL", colors.white, colors.black)
    centerText(12, "[3] Re-run Local Installer", colors.white, colors.black)
    centerText(13, "[4] Exit", colors.white, colors.black)

    centerText(h - 1, "Press a key...", colors.gray, colors.black)

    while true do
        local _, key = os.pullEvent("char")
        if key == "1" then
            if not url then
                url = promptForUrl()
            end
            if url then
                local content = downloadInstaller(url)
                if content then
                    installUpdate(content)
                    return
                end
            else
                centerText(h - 3, "No URL configured!", colors.red, colors.black)
                sleep(2)
            end
            return showMenu()
        elseif key == "2" then
            url = promptForUrl()
            return showMenu()
        elseif key == "3" then
            if fs.exists("install.lua") then
                term.setBackgroundColor(colors.black)
                term.clear()
                shell.run("install.lua")
            else
                centerText(h - 3, "No local installer found!", colors.red, colors.black)
                sleep(2)
                return showMenu()
            end
            return
        elseif key == "4" or key == "q" then
            term.setBackgroundColor(colors.black)
            term.clear()
            return
        end
    end
end

-- Run the menu
showMenu()
]])

writeFile('wordle/app.lua', [[
-- Daily Wordle: guess the day's five-letter Minecraft word in six tries. Every computer
-- on the server gets the same word on the same (UTC) day.
-- Type on the keyboard, touch the on-screen keys, or use the cabinet buttons: LEFT and
-- RIGHT move along the on-screen keys and CENTER presses the one lit up.
local rules=require('wordle.rules')
local render=require('wordle.render')
local M={}
local C=render.C
M.palette=render.palette
-- On-screen keys in reading order; the buttons walk this list.
local ROWS={'QWERTYUIOP','ASDFGHJKL','>ZXCVBNM<'}
local KEYS={}
for r,row in ipairs(ROWS) do for c in row:gmatch('.') do KEYS[#KEYS+1]={row=r,value=c=='>' and 'ENTER' or c=='<' and 'DEL' or c} end end
M.keys=KEYS
local PRAISE={'GENIUS','MAGNIFICENT','IMPRESSIVE','SPLENDID','GREAT','PHEW'}
-- {seconds after the cue, instrument, volume, pitch}
local CUES={
 type={{0,'hat',.4,16}},
 erase={{0,'hat',.4,10}},
 move={{0,'hat',.3,20}},
 bad={{0,'bass',1,6},{.1,'bass',1,4}},
 hit={{0,'bell',.8,18}},
 near={{0,'pling',.8,14}},
 miss={{0,'snare',.4,8}},
 win={{0,'chime',1,12},{.15,'chime',1,16},{.3,'chime',1,19},{.45,'chime',1,24}},
 lose={{0,'didgeridoo',1,8},{.3,'didgeridoo',1,4}},
}
M.cues=CUES
-- Animation timings, in seconds.
local FLIP=.25    -- between one tile starting to turn and the next
local TURN=.35    -- one tile turning over
local SHAKE=.5    -- a refused row shaking
local POP=.12     -- a typed tile's outline flashing
local HOP=.12     -- between solved tiles hopping
local HOPTIME=.36 -- one hop
-- Sizes, largest first: title rows tt, tiles tw x th with rg rows between them, keys
-- kw x kh with kg rows between the keyboard rows. A three-row title is the blocky one.
local SIZES={{3,7,3,1,5,3,1},{3,7,3,1,5,3,0},{3,7,3,1,5,1,0},{3,5,3,1,5,1,0},{1,5,3,1,5,1,0},{1,5,3,1,3,1,0},{1,3,1,1,3,1,0},{1,3,1,0,3,1,0}}
function M.layout(w,h)
 for _,s in ipairs(SIZES) do
  local tt,tw,th,rg,kw,kh,kg=table.unpack(s)
  local gridH=rules.TRIES*th+(rules.TRIES-1)*rg
  local kbH=3*kh+2*kg
  local gridW=rules.LENGTH*tw+rules.LENGTH-1
  local kbW=10*kw+9
  local used=tt+1+gridH+1+kbH+1+1
  if used<=h and gridW<=w and kbW<=w then
   local L={tt=tt,tw=tw,th=th,rg=rg,kw=kw,kh=kh,kg=kg,sw=(3*kw+1)/2}
   -- Centre the board and keyboard in the rows between the title and the message line.
   local spare=h-used
   L.gridY=tt+2+math.floor(spare/3)
   L.gridX=math.floor((w-gridW)/2)+1
   L.kbY=L.gridY+gridH+1+math.floor(spare/3)
   L.kbX=math.floor((w-kbW)/2)+1
   -- Where each on-screen key sits, in characters.
   L.keys={}
   local x,y,row=L.kbX,L.kbY,1
   for n,k in ipairs(KEYS) do
    if k.row~=row then row=k.row; y=y+kh+kg; x=L.kbX+(row==2 and math.floor((kw+1)/2) or 0) end
    local wd=(k.value=='ENTER' or k.value=='DEL') and L.sw or kw
    L.keys[n]={x=x,y=y,w=wd,value=k.value}
    x=x+wd+1
   end
   return L
  end
 end
end
local function centre(t,y,text,fg,bg)
 local w=t.getSize()
 t.setBackgroundColor(bg or C.bg); t.setCursorPos(1,y); t.clearLine()
 t.setTextColor(fg or C.text); t.setCursorPos(math.max(1,math.floor((w-#text)/2)+1),y); t.write(text)
end
-- The bottom row: three button slots, as wide as the cabinet buttons are apart.
local function slots(w)
 local a=math.floor(w/3)
 return {{x1=1,x2=a},{x1=a+1,x2=w-a},{x1=w-a+1,x2=w}}
end
M.slots=slots
-- opts: target, args, clock() (seconds, for animation), now() (UTC milliseconds, for the
-- day's word), button(event,p1), sound (casino.sound's play(at,instrument,volume,pitch) and
-- tick(now)), random(a,b) for the confetti
function M.run(opts)
 local t=opts.target
 local args=opts.args or {}
 local clock=opts.clock or function() return os.epoch('utc')/1000 end
 local now=opts.now or function() return os.epoch('utc') end
 local button=opts.button or require('input').getButton
 local sound=opts.sound or require('casino.sound')()
 local random=opts.random or math.random
 local monitorName
 for i,a in ipairs(args) do if a=='--monitor' then monitorName=args[i+1] end end
 if not monitorName and peripheral.getName then local ok,name=pcall(peripheral.getName,t); if ok then monitorName=name end end
 local view=render.new(t)
 local function cue(name)
  local at=clock()
  for _,n in ipairs(CUES[name]) do sound:play(at+n[1],n[2],n[3],n[4]) end
  sound:tick(at)
 end
 local puzzle,rows,typed,cursor,done,flash,flashUntil,shakeUntil,reveal,popAt,wonAt,confetti
 local function newGame()
  puzzle=rules.daily(now())
  rows={}; typed=''; done=nil; flash=nil; shakeUntil=0; reveal=nil; popAt=-1; wonAt=nil; confetti={}
  cursor=cursor or 1
 end
 newGame()
 local function say(text,secs) flash=text; flashUntil=clock()+(secs or 2) end
 local function message(w)
  if flash and clock()<flashUntil then return flash,C.text end
  if reveal then return '',C.text end
  if done then
   local left=86400000-now()%86400000
   local nextIn=('NEXT WORD IN %dH %02dM'):format(math.floor(left/3600000),math.floor(left%3600000/60000))
   local text=done=='win' and ('%s! SOLVED %d/%d'):format(PRAISE[#rows],#rows,rules.TRIES) or 'THE WORD WAS '..puzzle.word
   if #text+#nextIn+3<=w then text=text..' - '..nextIn end
   return text,done=='win' and C.grass or C.near
  end
  return ('GUESS %d OF %d'):format(#rows+1,rules.TRIES),C.key
 end
 -- How far tile i of row r has turned over, 0..1.
 local function flip(r,i)
  if not reveal or r<#rows then return 1 end
  return math.max(0,math.min(1,(clock()-reveal.start-(i-1)*FLIP)/TURN))
 end
 -- How many pixels tile i of the solved row is lifted.
 local function bounce(r,i)
  if not wonAt or r~=#rows then return 0 end
  local p=(clock()-wonAt-(i-1)*HOP)/HOPTIME
  if p<=0 or p>=1 then return 0 end
  return math.floor(3*math.sin(math.pi*p)+.5)
 end
 local function animating()
  local at=clock()
  return reveal or (flash and at<flashUntil+.1) or at<shakeUntil or at<popAt+POP or (wonAt and at<wonAt+HOP*rules.LENGTH+HOPTIME) or #confetti>0
 end
 local L
 local function draw()
  local w,h=t.getSize()
  L=M.layout(w,h)
  if not L then
   t.setBackgroundColor(C.bg); t.clear(); centre(t,1,'SCREEN TOO SMALL',C.bad); return
  end
  local at=clock()
  local seen=rules.keyboard(reveal and {table.unpack(rows,1,#rows-1)} or rows)
  local keys={}
  for n,k in ipairs(L.keys) do
   keys[n]={x=k.x,y=k.y,w=k.w,value=k.value,mark=seen[k.value],cursor=n==cursor and not done}
  end
  local shake=0
  if at<shakeUntil then shake=math.floor(2*math.sin((shakeUntil-at)*50)+.5) end
  view:draw({layout=L,puzzle=puzzle,rows=rows,typed=typed,done=done,tries=rules.TRIES,length=rules.LENGTH,
   keys=keys,flip=flip,bounce=bounce,shake=shake,pop=at<popAt+POP and #typed or nil,confetti=confetti})
  local text,fg=message(w)
  centre(t,h-1,text,fg)
  local bar=done and {'QUIT','NEXT PLAYER','QUIT'} or {'< KEY','PRESS '..KEYS[cursor].value,'KEY >'}
  for i,s in ipairs(slots(w)) do
   local wd=s.x2-s.x1+1
   t.setBackgroundColor(i==2 and C.miss or C.stone); t.setTextColor(C.text)
   t.setCursorPos(s.x1,h); t.write((' '):rep(wd))
   t.setCursorPos(s.x1+math.floor((wd-#bar[i])/2),h); t.write(bar[i])
  end
 end
 local function hitWhat(x,y)
  if not L then return end
  local w,h=t.getSize()
  if y==h then for i,s in ipairs(slots(w)) do if x>=s.x1 and x<=s.x2 then return ({'LEFT','CENTER','RIGHT'})[i] end end end
  for _,k in ipairs(L.keys) do if x>=k.x and x<k.x+k.w and y>=k.y and y<k.y+L.kh then return k.value end end
 end
 local function refuse(text) say(text); shakeUntil=clock()+SHAKE; cue('bad') end
 local function submit()
  if #typed<rules.LENGTH then return refuse('NOT ENOUGH LETTERS') end
  if not rules.valid(typed) then return refuse('NOT IN WORD LIST') end
  rows[#rows+1]={word=typed,marks=rules.score(typed,puzzle.word)}
  typed=''
  reveal={start=clock(),cued=0}
 end
 local function finish()
  local last=rows[#rows]
  if last.word==puzzle.word then
   done='win'; wonAt=clock(); cue('win')
   local w,h=t.getSize()
   local shades={C.hit,C.hitLight,C.near,C.nearLight,C.grass,C.cursorLight,C.text}
   for _=1,math.floor(w*1.2) do
    confetti[#confetti+1]={x=random(1,w*2),y=-random(0,h*2),vx=(random()-.5)*12,vy=random()*20,c=shades[random(1,#shades)]}
   end
  elseif #rows>=rules.TRIES then done='lose'; cue('lose') end
 end
 -- One action: a letter, ENTER, DEL, or a cabinet button. Returns true to quit.
 local function act(v)
  if reveal then return end
  if done then
   if v=='CENTER' then newGame()
   elseif v=='LEFT' or v=='RIGHT' then return true end
   return
  end
  if v=='LEFT' then cursor=(cursor-2)%#KEYS+1; cue('move'); return end
  if v=='RIGHT' then cursor=cursor%#KEYS+1; cue('move'); return end
  if v=='CENTER' then v=KEYS[cursor].value end
  if v=='ENTER' then submit()
  elseif v=='DEL' then if #typed>0 then typed=typed:sub(1,-2); cue('erase') end
  elseif #typed<rules.LENGTH then typed=typed..v; popAt=clock(); cue('type') end
 end
 local timer=os.startTimer(.05)
 local last=clock()
 local lastSecond=-1
 draw()
 while true do
  local e,p1,p2,p3=os.pullEventRaw()
  if e=='terminate' then return end
  local v
  if e=='timer' and p1==timer then
   local at=clock()
   local dt=math.min(.2,at-last); last=at
   local changed=false
   if reveal then
    -- Each tile sounds its mark as it shows its new face, halfway over.
    while reveal.cued<rules.LENGTH and at>=reveal.start+reveal.cued*FLIP+TURN/2 do
     reveal.cued=reveal.cued+1; cue(rows[#rows].marks[reveal.cued])
    end
    if at>=reveal.start+(rules.LENGTH-1)*FLIP+TURN then reveal=nil; finish(); changed=true end
   end
   if #confetti>0 then
    local _,h=t.getSize()
    for n=#confetti,1,-1 do
     local p=confetti[n]
     p.vy=p.vy+40*dt; p.x=p.x+p.vx*dt; p.y=p.y+p.vy*dt
     if p.y>h*3 then table.remove(confetti,n) end
    end
   end
   sound:tick(at)
   -- Redraw while something moves, and once a second for the countdown and messages.
   local second=math.floor(at)
   if changed or animating() or second~=lastSecond then draw(); lastSecond=second end
   timer=os.startTimer(.05)
  elseif e=='char' and p1:match('^%a$') then v=p1:upper()
  elseif e=='char' then v=button(e,p1)
  elseif e=='key' and p1==keys.enter then v='ENTER'
  elseif e=='key' and p1==keys.backspace then v='DEL'
  elseif e=='key' then
   -- Letter keys arrive again as char events; anything else may be a cabinet button.
   local name=keys.getName(p1) or ''
   if not name:match('^%a$') then v=button(e,p1) end
  elseif e=='redstone' then v=button(e,p1)
  elseif e=='mouse_click' and not monitorName then v=hitWhat(p2,p3)
  elseif e=='monitor_touch' and p1==monitorName then v=hitWhat(p2,p3)
  elseif e=='term_resize' or e=='monitor_resize' then draw() end
  if v then
   if act(v) then return end
   draw()
  end
 end
end
return M
]])

